select r.id, c from biz.roles r, unnest(array['law.view','law.manage','law.send','law.ai']) c
where r.tenant_id is null and r.name in ('Manager','HR')
on conflict do nothing;

insert into biz.role_permissions (role_id, permission_code)
select r.id, c from biz.roles r, unnest(array['law.view','law.compliance']) c
where r.tenant_id is null and r.name = 'Accountant'
on conflict do nothing;

insert into biz.role_permissions (role_id, permission_code)
select r.id, c from biz.roles r, unnest(array['law.view','law.manage','law.send']) c
where r.tenant_id is null and r.name = 'Sales'
