  course int not null default 1,
  station_id uuid references biz.kitchen_stations(id) on delete set null,
  status text not null default 'new' check (status in ('new','sent','preparing','ready','served','void')),
  source text not null default 'staff',
  sent_at timestamptz,
  ready_at timestamptz,
  served_at timestamptz,
  void_reason text,
  voided_by uuid,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);
create index on biz.order_items (order_id);
create index on biz.order_items (tenant_id, status) where status in ('sent','preparing');

-- ===== Bookings =====
create table biz.booking_services (
