-- ===== Helpers =====
create or replace function biz.ensure_ext_defaults(p_tenant uuid)
returns void language plpgsql security definer set search_path = biz, public as $$
declare pid uuid; vid uuid;
begin
  insert into ext_settings (tenant_id) values (p_tenant) on conflict do nothing;
  insert into kitchen_stations (tenant_id, name) values (p_tenant, 'Kitchen') on conflict do nothing;
  if (select service_variant_id from ext_settings where tenant_id = p_tenant) is null then
    insert into products (tenant_id, name, kind, on_menu) values (p_tenant, 'Service charge', 'service', false) returning id into pid;
    insert into product_variants (tenant_id, product_id, sku, price, track_stock) values (p_tenant, pid, 'SVC-CHARGE', 0, false)
      on conflict (tenant_id, sku) do update set track_stock = false returning id into vid;
    update ext_settings set service_variant_id = vid where tenant_id = p_tenant;
  end if;
  if (select delivery_variant_id from ext_settings where tenant_id = p_tenant) is null then
    insert into products (tenant_id, name, kind, on_menu) values (p_tenant, 'Delivery fee', 'service', false) returning id into pid;
    insert into product_variants (tenant_id, product_id, sku, price, track_stock) values (p_tenant, pid, 'DELIVERY-FEE', 0, false)
      on conflict (tenant_id, sku) do update set track_stock = false returning id into vid;
    update ext_settings set delivery_variant_id = vid where tenant_id = p_tenant;
  end if;
end $$;

create or replace function biz.ext_module_on()
returns trigger language plpgsql security definer set search_path = biz, public as $$
begin
  if new.module = 'EXT' and new.enabled then perform ensure_ext_defaults(new.tenant_id); end if;
  return null;
end $$;
create trigger trg_ext_module_on after insert or update on biz.tenant_modules for each row execute function biz.ext_module_on();
do $$ declare t record; begin
  for t in select tenant_id from biz.tenant_modules where module = 'EXT' and enabled loop
    perform biz.ensure_ext_defaults(t.tenant_id);
  end loop;
end $$;

create or replace function biz.next_order_no(p_outlet uuid)
returns text language plpgsql security definer set search_path = biz, public as $$
declare d date := (now() at time zone tenant_tz((select tenant_id from outlets where id = p_outlet), p_outlet))::date; n int;
begin
  insert into order_counters (outlet_id, day) values (p_outlet, d) on conflict do nothing;
  update order_counters set next_no = next_no + 1 where outlet_id = p_outlet and day = d returning next_no - 1 into n;
  return '#' || lpad(n::text, 3, '0');
end $$;

-- Find or create a customer contact by phone/email
create or replace function biz.contact_for(p_tenant uuid, p_name text, p_phone text, p_email text, p_source text)
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare cid uuid; ph text := norm_phone(p_phone); em text := lower(nullif(trim(p_email), ''));
begin
  if ph is null and em is null then return null; end if;
  select id into cid from contacts
  where tenant_id = p_tenant and ((ph is not null and norm_phone(phone) = ph) or (em is not null and lower(email) = em))
  order by created_at limit 1;
  if cid is null then
    insert into contacts (tenant_id, kind, name, phone, email, source, lifecycle)
    values (p_tenant, 'customer', coalesce(nullif(trim(p_name), ''), coalesce(p_phone, em)), nullif(trim(p_phone), ''), em, p_source, 'customer')
    returning id into cid;
  end if;
  return cid;
end $$;

create or replace function biz.order_recalc(p_order uuid)
returns void language sql security definer set search_path = biz, public as $$
  update orders set items_total = coalesce((select sum(round(qty * (unit_price + modifiers_total), 2)) from order_items
                                            where order_id = p_order and status <> 'void'), 0)
  where id = p_order;
$$;

create or replace function biz.order_item_after()
returns trigger language plpgsql security definer set search_path = biz, public as $$
begin
  perform order_recalc(coalesce(new.order_id, old.order_id));
  return null;
end $$;
create trigger trg_order_item_after after insert or update or delete on biz.order_items for each row execute function biz.order_item_after();

-- Message the customer about their order (if they left a phone/email)
create or replace function biz.notify_order_customer(p_order uuid, p_text text)
returns void language plpgsql security definer set search_path = biz, public as $$
declare o orders; base text; biz text;
begin
  select * into o from orders where id = p_order;
  if o.customer_phone is null and o.customer_email is null then return; end if;
  select web_base_url into base from ext_settings where tenant_id = o.tenant_id;
  select name into biz from tenants where id = o.tenant_id;
  insert into outbound_messages (tenant_id, channel, to_address, subject, body)
  values (o.tenant_id, case when o.customer_email is not null then 'email' else 'whatsapp' end,
          coalesce(lower(o.customer_email), norm_phone(o.customer_phone)),
          biz || ' order ' || o.order_no,
          biz || ': order ' || o.order_no || ' ' || p_text
          || case when base is not null then ' Track it: ' || rtrim(base, '/') || '/order.html?o=' || o.track_token else '' end);
end $$;

-- ===== Taking orders (staff) =====
create or replace function biz.open_order(p_outlet uuid, p_channel text, p_table uuid default null, p_guests int default null,
                                             p_customer jsonb default '{}')
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare v_tenant uuid; v_id uuid; st ext_settings; v_contact uuid; v_fulfil text;
begin
  select tenant_id into v_tenant from outlets where id = p_outlet;
  if v_tenant is null or not has_perm(v_tenant, 'ord.take') then raise exception 'Not allowed'; end if;
  if p_table is not null then
    if not exists (select 1 from dining_tables where id = p_table and outlet_id = p_outlet and active) then raise exception 'Unknown table'; end if;
    select id into v_id from orders where table_id = p_table and status in ('pending','open','ready');
    if v_id is not null then return v_id; end if;
  end if;
  select * into st from ext_settings where tenant_id = v_tenant;
  v_contact := contact_for(v_tenant, p_customer->>'name', p_customer->>'phone', p_customer->>'email', 'walk-in');
  v_fulfil := case p_channel when 'dine_in' then 'here' when 'delivery' then 'delivery' else 'pickup' end;
  insert into orders (tenant_id, outlet_id, order_no, channel, table_id, guests, contact_id, customer_name, customer_phone, customer_email,
                      fulfilment, delivery_address, delivery_postcode, delivery_fee, external_provider, external_ref, notes,
                      service_charge_pct, status, accepted_at)
  values (v_tenant, p_outlet, next_order_no(p_outlet), p_channel, p_table, p_guests, v_contact,
          nullif(trim(p_customer->>'name'), ''), nullif(trim(p_customer->>'phone'), ''), lower(nullif(trim(p_customer->>'email'), '')),
          v_fulfil, nullif(trim(p_customer->>'address'), ''), nullif(trim(p_customer->>'postcode'), ''),
          coalesce((p_customer->>'delivery_fee')::numeric, 0),
          nullif(p_customer->>'external_provider', ''), nullif(p_customer->>'external_ref', ''), nullif(trim(p_customer->>'notes'), ''),
          case when p_channel = 'dine_in' or not coalesce(st.service_charge_dine_in_only, true) then coalesce(st.service_charge_pct, 0) else 0 end,
          'open', now())
  returning id into v_id;
  return v_id;
end $$;

-- Validates items against the menu and modifier rules; used by staff and the public ordering page.
-- p_items: [{"variant_id":"…","qty":1,"modifier_ids":["…"],"note":"no onion","course":1}]
create or replace function biz.order_add_items_internal(p_order uuid, p_items jsonb, p_source text, p_status text)
returns int language plpgsql security definer set search_path = biz, public as $$
declare o orders; it jsonb; v product_variants; p products; mods jsonb; mtotal numeric; g record; cnt int; n int := 0; q numeric;
begin
  select * into o from orders where id = p_order for update;
  if o.status not in ('pending','open','ready') then raise exception 'Order is %', o.status; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'No items'; end if;
  if jsonb_array_length(p_items) > 40 then raise exception 'Too many lines in one go'; end if;
  for it in select * from jsonb_array_elements(p_items) loop
    select * into v from product_variants where id = (it->>'variant_id')::uuid and tenant_id = o.tenant_id and active;
    if not found then raise exception 'Unknown item'; end if;
    select * into p from products where id = v.product_id;
    if not p.active then raise exception '% is not available', p.name; end if;
    if p.sold_out then raise exception '% is sold out', p.name; end if;
    q := coalesce((it->>'qty')::numeric, 1);
    if q <= 0 or q > 50 then raise exception 'Check the quantity for %', p.name; end if;
    -- modifiers: must belong to this product's groups and respect min/max per group
    select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.name, 'price', m.price_delta, 'group_id', m.group_id) order by mg.name, m.sort_order), '[]'),
           coalesce(sum(m.price_delta), 0)
      into mods, mtotal
    from modifiers m join modifier_groups mg on mg.id = m.group_id
    join product_modifier_groups pmg on pmg.group_id = m.group_id and pmg.product_id = p.id
    where m.active and m.id in (select (x)::uuid from jsonb_array_elements_text(coalesce(it->'modifier_ids', '[]')) x);
    if jsonb_array_length(mods) <> jsonb_array_length(coalesce(it->'modifier_ids', '[]')) then
      raise exception 'An option chosen for % is not available', p.name;
    end if;
    for g in select mg.* from modifier_groups mg join product_modifier_groups pmg on pmg.group_id = mg.id where pmg.product_id = p.id loop
      select count(*) into cnt from jsonb_array_elements(mods) x where (x->>'group_id')::uuid = g.id;
      if cnt < g.min_select then raise exception 'Choose % for %', g.name, p.name; end if;
      if cnt > g.max_select then raise exception 'Choose at most % for % (%)', g.max_select, g.name, p.name; end if;
    end loop;
    insert into order_items (tenant_id, order_id, variant_id, name, qty, unit_price, modifiers, modifiers_total, note, course, station_id,
                             status, source, sent_at)
    values (o.tenant_id, o.id, v.id, p.name || coalesce(' — ' || v.name, ''), q, v.price, mods, mtotal,
            left(nullif(trim(it->>'note'), ''), 200), coalesce((it->>'course')::int, 1), p.station_id,
            p_status, p_source, case when p_status = 'sent' then now() end);
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function biz.add_order_items(p_order uuid, p_items jsonb)
returns int language plpgsql security definer set search_path = biz, public as $$
declare o orders;
begin
  select * into o from orders where id = p_order;
  if not found or not has_perm(o.tenant_id, 'ord.take') then raise exception 'Not allowed'; end if;
  return order_add_items_internal(p_order, p_items, 'staff', 'new');
end $$;

-- Send new items to the kitchen (and accept a pending QR/online order)
create or replace function biz.send_order(p_order uuid)
returns int language plpgsql security definer set search_path = biz, public as $$
declare o orders; n int;
begin
  select * into o from orders where id = p_order for update;
  if not found or not has_perm(o.tenant_id, 'ord.take') then raise exception 'Not allowed'; end if;
  if o.status not in ('pending','open','ready') then raise exception 'Order is %', o.status; end if;
  update order_items set status = 'sent', sent_at = now() where order_id = o.id and status = 'new';
  get diagnostics n = row_count;
  if o.status = 'pending' then
    update orders set status = 'open', accepted_at = now() where id = o.id;
    perform notify_order_customer(o.id, 'has been accepted and is being prepared.');
  elsif n > 0 and o.status = 'ready' then
    update orders set status = 'open', ready_at = null where id = o.id;
  end if;
  return n;
end $$;

-- Kitchen display: move items along; when everything is ready the order is ready
create or replace function biz.set_items_status(p_items uuid[], p_status text)
returns int language plpgsql security definer set search_path = biz, public as $$
declare v_tenant uuid; n int; o record;
begin
  if p_status not in ('preparing','ready','served','sent') then raise exception 'Unknown status'; end if;
  select distinct tenant_id into v_tenant from order_items where id = any(p_items);
  if v_tenant is null then return 0; end if;
  if (select count(distinct tenant_id) from order_items where id = any(p_items)) > 1 then raise exception 'Mixed businesses'; end if;
  if not (has_perm(v_tenant, 'ord.kitchen') or (p_status = 'served' and has_perm(v_tenant, 'ord.take'))) then raise exception 'Not allowed'; end if;
  update order_items set status = p_status,
    ready_at = case when p_status = 'ready' then now() when p_status = 'sent' then null else ready_at end,
    served_at = case when p_status = 'served' then now() else served_at end
  where id = any(p_items) and status not in ('void','new');
  get diagnostics n = row_count;
  for o in select distinct order_id from order_items where id = any(p_items) loop
    if not exists (select 1 from order_items where order_id = o.order_id and status in ('new','sent','preparing'))
       and exists (select 1 from orders where id = o.order_id and status = 'open') then
      update orders set status = 'ready', ready_at = now() where id = o.order_id and channel <> 'dine_in';
      if found then perform notify_order_customer(o.order_id, 'is ready.'); end if;
    end if;
  end loop;
  return n;
end $$;

create or replace function biz.void_order_item(p_item uuid, p_reason text)
returns void language plpgsql security definer set search_path = biz, public as $$
declare i order_items; o orders;
begin
  select * into i from order_items where id = p_item;
  select * into o from orders where id = i.order_id;
  if not found or not has_perm(o.tenant_id, 'ord.take') then raise exception 'Not allowed'; end if;
  if o.status not in ('pending','open','ready') then raise exception 'Order is %', o.status; end if;
  if i.status = 'new' then
    delete from order_items where id = i.id;           -- never sent: just remove
  else
    if not has_perm(o.tenant_id, 'ord.void') then raise exception 'A manager must void items already sent to the kitchen'; end if;
    if coalesce(length(trim(p_reason)), 0) < 3 then raise exception 'Give a reason'; end if;
    update order_items set status = 'void', void_reason = trim(p_reason), voided_by = auth.uid() where id = i.id;
  end if;
end $$;

create or replace function biz.move_order_table(p_order uuid, p_table uuid)
returns void language plpgsql security definer set search_path = biz, public as $$
declare o orders;
begin
  select * into o from orders where id = p_order;
  if not found or not has_perm(o.tenant_id, 'ord.take') then raise exception 'Not allowed'; end if;
  if not exists (select 1 from dining_tables where id = p_table and outlet_id = o.outlet_id and active) then raise exception 'Unknown table'; end if;
  if exists (select 1 from orders where table_id = p_table and status in ('pending','open','ready') and id <> o.id) then
    raise exception 'That table already has an open order';
  end if;
  update orders set table_id = p_table, channel = 'dine_in' where id = o.id;
end $$;

create or replace function biz.cancel_order(p_order uuid, p_reason text)
returns void language plpgsql security definer set search_path = biz, public as $$
declare o orders;
begin
  select * into o from orders where id = p_order for update;
  if not found or not has_perm(o.tenant_id, 'ord.take') then raise exception 'Not allowed'; end if;
  if o.status in ('completed','cancelled') then raise exception 'Order is %', o.status; end if;
  if exists (select 1 from order_items where order_id = o.id and status not in ('new','void')) and not has_perm(o.tenant_id, 'ord.void') then
    raise exception 'A manager must cancel an order that the kitchen has started';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 3 then raise exception 'Give a reason'; end if;
  update order_items set status = 'void', void_reason = 'Order cancelled' where order_id = o.id and status <> 'void';
  update orders set status = 'cancelled', cancelled_at = now(), cancel_reason = trim(p_reason) where id = o.id;
  if o.status = 'pending' or o.source in ('web','qr') then
    perform notify_order_customer(o.id, 'could not be accepted: ' || trim(p_reason));
  end if;
end $$;

-- Lines that will be sold at checkout (items + service charge + delivery fee), with tax as the POS will charge it
create or replace function biz.order_quote(p_order uuid)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare o orders; st ext_settings; lines jsonb := '[]'; r record; t record; v_net numeric; v_tax numeric; v_tot numeric;
        sub numeric := 0; tax numeric := 0; total numeric := 0; svc numeric; unlinked int;
begin
  select * into o from orders where id = p_order;
  if not found or not (has_perm(o.tenant_id, 'ord.view') or has_perm(o.tenant_id, 'pos.sale.create')) then raise exception 'Not allowed'; end if;
  select * into st from ext_settings where tenant_id = o.tenant_id;
  select count(*) into unlinked from order_items where order_id = o.id and status <> 'void' and variant_id is null;
  for r in
    select x.variant_id, x.name, x.qty, x.price, pr.tax_code from (
      select oi.variant_id, oi.name || case when jsonb_array_length(oi.modifiers) > 0
               then ' (' || (select string_agg(m->>'name', ', ') from jsonb_array_elements(oi.modifiers) m) || ')' else '' end as name,
             oi.qty, oi.unit_price + oi.modifiers_total as price, oi.created_at
      from order_items oi where oi.order_id = o.id and oi.status <> 'void' and oi.variant_id is not null
      union all
      select st.service_variant_id, 'Service charge ' || rtrim(to_char(o.service_charge_pct, 'FM990.##'), '.') || '%', 1,
             round(o.items_total * o.service_charge_pct / 100, 2), 'infinity'::timestamptz
      where o.service_charge_pct > 0 and o.items_total > 0
      union all
      select st.delivery_variant_id, 'Delivery fee', 1, o.delivery_fee, 'infinity'::timestamptz where o.delivery_fee > 0
    ) x join product_variants pv on pv.id = x.variant_id join products pr on pr.id = pv.product_id
    order by x.created_at
  loop
    select * into t from resolve_tax(o.tenant_id, o.outlet_id, r.tax_code, current_date);
    v_net := round(r.price * r.qty, 2);
    if coalesce(t.inclusive, false) then v_tax := round(v_net - v_net / (1 + coalesce(t.rate, 0)), 2); v_tot := v_net;
    else v_tax := round(v_net * coalesce(t.rate, 0), 2); v_tot := v_net + v_tax; end if;
    lines := lines || jsonb_build_object('variant_id', r.variant_id, 'name', r.name, 'qty', r.qty, 'unit_price', r.price,
                                         'tax', v_tax, 'total', v_tot, 'tax_name', t.name);
    sub := sub + v_net; tax := tax + v_tax; total := total + v_tot;
  end loop;
  return jsonb_build_object('order_no', o.order_no, 'lines', lines, 'subtotal', sub, 'tax', tax, 'total', total,
                            'unlinked_items', unlinked, 'prepaid', o.prepaid, 'prepaid_amount', o.prepaid_amount);
end $$;

-- Pay and close: becomes a normal POS sale (receipt, stock, accounts, loyalty)
create or replace function biz.checkout_order(p_order uuid, p_payments jsonb, p_shift uuid default null, p_client_sale_id uuid default null)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare o orders; q jsonb; v_sale sales; l jsonb; v_lines jsonb := '[]';
begin
  select * into o from orders where id = p_order for update;
  if not found then raise exception 'Unknown order'; end if;
  if o.status in ('completed','cancelled') then raise exception 'Order is %', o.status; end if;
  if exists (select 1 from order_items where order_id = o.id and status = 'new') then
    raise exception 'Some items were not sent to the kitchen — send or remove them first';
  end if;
  q := order_quote(o.id);
  if (q->>'unlinked_items')::int > 0 then raise exception 'Link the online items to your products (by SKU) before checkout'; end if;
  if jsonb_array_length(q->'lines') = 0 then raise exception 'Nothing to charge'; end if;
  for l in select * from jsonb_array_elements(q->'lines') loop
    v_lines := v_lines || jsonb_build_object('variant_id', l->>'variant_id', 'qty', (l->>'qty')::numeric, 'unit_price', (l->>'unit_price')::numeric);
  end loop;
  v_sale := complete_sale(jsonb_build_object(
    'outlet_id', o.outlet_id, 'shift_id', p_shift, 'client_sale_id', coalesce(p_client_sale_id, gen_random_uuid()),
    'customer_id', o.contact_id, 'lines', v_lines, 'payments', p_payments,
    'note', 'Order ' || o.order_no || coalesce(' · ' || (select name from dining_tables where id = o.table_id), '')
            || coalesce(' · ' || o.external_provider || ' ' || o.external_ref, '')));
  update order_items set status = 'served', served_at = coalesce(served_at, now()) where order_id = o.id and status in ('sent','preparing','ready');
  update orders set status = 'completed', completed_at = now(), sale_id = v_sale.id where id = o.id;
  update bookings set status = 'completed', sale_id = v_sale.id where order_id = o.id and status = 'arrived';
  return jsonb_build_object('sale_id', v_sale.id, 'receipt_no', v_sale.receipt_no, 'total', v_sale.total);
end $$;

-- Delivery
create or replace function biz.assign_rider(p_order uuid, p_rider uuid)
returns void language plpgsql security definer set search_path = biz, public as $$
declare o orders;
begin
  select * into o from orders where id = p_order;
  if not found or not has_perm(o.tenant_id, 'ord.take') then raise exception 'Not allowed'; end if;
  if o.fulfilment <> 'delivery' then raise exception 'Not a delivery order'; end if;
  if p_rider is not null and not exists (select 1 from memberships m join role_permissions rp on rp.role_id = m.role_id
       where m.tenant_id = o.tenant_id and m.user_id = p_rider and m.active and rp.permission_code = 'ord.deliver') then
    raise exception 'That person is not set up as a rider';
  end if;
  update orders set rider_id = p_rider where id = o.id;
end $$;

create or replace function biz.order_riders(p_tenant uuid)
returns table (user_id uuid, name text)
language sql stable security definer set search_path = biz, public as $$
  select m.user_id, coalesce((select full_name from employees e where e.tenant_id = p_tenant and e.user_id = m.user_id limit 1),
                             (select email from auth.users u where u.id = m.user_id))
  from memberships m join role_permissions rp on rp.role_id = m.role_id and rp.permission_code = 'ord.deliver'
  where m.tenant_id = p_tenant and m.active and has_perm(p_tenant, 'ord.take')
  order by 2;
$$;

create or replace function biz.delivery_update(p_order uuid, p_status text)
returns void language plpgsql security definer set search_path = biz, public as $$
declare o orders;
begin
  select * into o from orders where id = p_order for update;
  if not found then raise exception 'Unknown order'; end if;
  if not (has_perm(o.tenant_id, 'ord.take') or (o.rider_id = auth.uid() and has_perm(o.tenant_id, 'ord.deliver'))) then
    raise exception 'Not allowed';
  end if;
  if p_status = 'out_for_delivery' then
    if o.status not in ('open','ready') then raise exception 'Order is %', o.status; end if;
    update orders set status = 'out_for_delivery', dispatched_at = now() where id = o.id;
    perform notify_order_customer(o.id, 'is on the way.');
  elsif p_status = 'delivered' then
    if o.status <> 'out_for_delivery' then raise exception 'Order is not out for delivery'; end if;
    update orders set status = 'delivered', delivered_at = now() where id = o.id;
  else
    raise exception 'Unknown status';
  end if;
end $$;

-- ===== Public (customer) RPCs — no login =====
-- Key = a table's QR token (order at the table) or the business online key (pickup / delivery / bookings)
create or replace function biz.resolve_public_key(p_key text, out tenant_id uuid, out outlet_id uuid, out table_id uuid, out mode text)
language plpgsql stable security definer set search_path = biz, public as $$
begin
  select t.tenant_id, t.outlet_id, t.id, 'table' into tenant_id, outlet_id, table_id, mode
  from dining_tables t join ext_settings s on s.tenant_id = t.tenant_id
  where t.qr_token = p_key and t.active and s.qr_ordering;
  if tenant_id is null then
    select s.tenant_id, (select o.id from outlets o where o.tenant_id = s.tenant_id order by o.created_at limit 1), null, 'online'
      into tenant_id, outlet_id, table_id, mode
    from ext_settings s where s.online_key = p_key;
  end if;
  if tenant_id is null or length(coalesce(p_key, '')) < 32
     or not exists (select 1 from tenant_modules m where m.tenant_id = resolve_public_key.tenant_id and m.module = 'EXT' and m.enabled) then
    raise exception 'This link is not valid';
  end if;
end $$;

create or replace function biz.open_now(p_outlet uuid)
returns boolean language sql stable security definer set search_path = biz, public as $$
  select case when not exists (select 1 from business_hours where outlet_id = p_outlet) then true
    else exists (select 1 from business_hours h
                 where h.outlet_id = p_outlet
                   and h.weekday = extract(isodow from now() at time zone tenant_tz(h.tenant_id, p_outlet))::int
                   and (now() at time zone tenant_tz(h.tenant_id, p_outlet))::time between h.opens and h.closes) end;
$$;

create or replace function biz.public_menu(p_key text)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare k record; st ext_settings; biz tenants;
begin
  select * into k from resolve_public_key(p_key);
  select * into st from ext_settings where tenant_id = k.tenant_id;
  select * into biz from tenants where id = k.tenant_id;
  return jsonb_build_object(
    'business', biz.name, 'currency', biz.base_currency, 'mode', k.mode,
    'table', (select name from dining_tables where id = k.table_id),
    'outlet', (select name from outlets where id = k.outlet_id),
    'open_now', open_now(k.outlet_id),
    'ordering', case when k.mode = 'table' then st.qr_ordering else st.online_ordering end,
    'pickup', st.pickup_enabled, 'delivery', st.delivery_enabled, 'prep_minutes', st.prep_minutes,
    'service_charge_pct', case when k.mode = 'table' or not st.service_charge_dine_in_only then st.service_charge_pct else 0 end,
    'zones', (select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'name', z.name, 'fee', z.fee, 'min_order', z.min_order, 'postcodes', z.postcodes) order by z.fee), '[]')
              from delivery_zones z where z.outlet_id = k.outlet_id and z.active),
    'categories', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.sort_order, c.name), '[]')
                   from categories c where c.tenant_id = k.tenant_id
                     and exists (select 1 from products p where p.category_id = c.id and p.on_menu and p.active)),
    'items', (select coalesce(jsonb_agg(jsonb_build_object(
                'product_id', p.id, 'variant_id', v.id, 'name', p.name, 'variant', v.name, 'description', p.description,
                'category_id', p.category_id, 'price', v.price, 'sold_out', p.sold_out,
                'groups', (select coalesce(jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name, 'min', g.min_select, 'max', g.max_select,
                             'options', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.name, 'price', m.price_delta) order by m.sort_order, m.name), '[]')
                                         from modifiers m where m.group_id = g.id and m.active)) order by pmg.sort_order, g.name), '[]')
                           from product_modifier_groups pmg join modifier_groups g on g.id = pmg.group_id where pmg.product_id = p.id))
              order by p.menu_sort, p.name, v.price), '[]')
              from products p join product_variants v on v.product_id = p.id and v.active
              where p.tenant_id = k.tenant_id and p.on_menu and p.active and p.kind <> 'bundle'
                and v.id is distinct from st.service_variant_id and v.id is distinct from st.delivery_variant_id)
  );
end $$;

-- p_customer: {"name","phone","email","note","fulfilment":"here|pickup|delivery","address","postcode","zone_id","scheduled_for"}
create or replace function biz.public_place_order(p_key text, p_items jsonb, p_customer jsonb)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare k record; st ext_settings; o orders; v_id uuid; z delivery_zones; v_fulfil text; v_status text; recent int; ph text; v_contact uuid;
begin
  select * into k from resolve_public_key(p_key);
  select * into st from ext_settings where tenant_id = k.tenant_id;
  ph := norm_phone(p_customer->>'phone');
  if k.mode = 'table' then
    if not st.qr_ordering then raise exception 'Ordering at the table is switched off — please ask the staff'; end if;
    select count(*) into recent from order_items oi join orders oo on oo.id = oi.order_id
      where oo.table_id = k.table_id and oi.source = 'qr' and oi.created_at > now() - interval '10 minutes';
    if recent > 60 then raise exception 'Too many orders from this table — please ask the staff'; end if;
    v_fulfil := 'here';
  else
    if not st.online_ordering then raise exception 'Online ordering is closed'; end if;
    if not open_now(k.outlet_id) and p_customer->>'scheduled_for' is null then raise exception 'We are closed right now — choose a later time'; end if;
    if ph is null or length(ph) < 9 then raise exception 'Enter your phone number'; end if;
    if coalesce(length(trim(p_customer->>'name')), 0) < 2 then raise exception 'Enter your name'; end if;
    select count(*) into recent from orders where tenant_id = k.tenant_id and norm_phone(customer_phone) = ph and status = 'pending';
    if recent >= 3 then raise exception 'You already have orders waiting to be accepted'; end if;
    select count(*) into recent from orders where tenant_id = k.tenant_id and status = 'pending' and source = 'web';
    if recent >= 50 then raise exception 'We are very busy — please try again shortly'; end if;
    v_fulfil := coalesce(p_customer->>'fulfilment', 'pickup');
    if v_fulfil not in ('pickup','delivery') then raise exception 'Choose pickup or delivery'; end if;
    if v_fulfil = 'pickup' and not st.pickup_enabled then raise exception 'Pickup is not available'; end if;
    if v_fulfil = 'delivery' then
      if not st.delivery_enabled then raise exception 'Delivery is not available'; end if;
      select * into z from delivery_zones where id = (p_customer->>'zone_id')::uuid and outlet_id = k.outlet_id and active;
      if not found then raise exception 'Choose your delivery area'; end if;
      if cardinality(z.postcodes) > 0 and not (coalesce(trim(p_customer->>'postcode'), '') = any(z.postcodes)) then
        raise exception 'We don''t deliver to that postcode in %', z.name;
      end if;
      if coalesce(length(trim(p_customer->>'address')), 0) < 10 then raise exception 'Enter your full delivery address'; end if;
    end if;
    if (p_customer->>'scheduled_for') is not null
       and ((p_customer->>'scheduled_for')::timestamptz < now() or (p_customer->>'scheduled_for')::timestamptz > now() + interval '7 days') then
      raise exception 'Choose a time within the next 7 days';
    end if;
  end if;

  if k.mode = 'table' then
    select * into o from orders where table_id = k.table_id and status in ('pending','open','ready');
  end if;
  if o.id is null then
    v_contact := contact_for(k.tenant_id, p_customer->>'name', p_customer->>'phone', p_customer->>'email', case when k.mode = 'table' then 'qr' else 'website' end);
    insert into orders (tenant_id, outlet_id, order_no, channel, source, table_id, status, contact_id, customer_name, customer_phone, customer_email,
                        notes, fulfilment, scheduled_for, delivery_address, delivery_postcode, delivery_zone_id, delivery_fee, service_charge_pct)
    values (k.tenant_id, k.outlet_id, next_order_no(k.outlet_id), case when k.mode = 'table' then 'dine_in' else 'online' end,
            case when k.mode = 'table' then 'qr' else 'web' end, k.table_id,
            case when k.mode = 'table' and st.qr_auto_send then 'open' else 'pending' end, v_contact,
            left(nullif(trim(p_customer->>'name'), ''), 80), left(nullif(trim(p_customer->>'phone'), ''), 30),
            lower(left(nullif(trim(p_customer->>'email'), ''), 120)), left(nullif(trim(p_customer->>'note'), ''), 300),
            v_fulfil, (p_customer->>'scheduled_for')::timestamptz,
            case when v_fulfil = 'delivery' then left(trim(p_customer->>'address'), 300) end,
            case when v_fulfil = 'delivery' then left(trim(p_customer->>'postcode'), 10) end,
            case when v_fulfil = 'delivery' then z.id end, case when v_fulfil = 'delivery' then z.fee else 0 end,
            case when k.mode = 'table' or not st.service_charge_dine_in_only then st.service_charge_pct else 0 end)
    returning * into o;
  end if;
  perform order_add_items_internal(o.id, p_items, 'qr',
    case when k.mode = 'table' and st.qr_auto_send and o.status <> 'pending' then 'sent' else 'new' end);
  select * into o from orders where id = o.id;
  if v_fulfil = 'delivery' and o.items_total < z.min_order then
    raise exception 'Minimum order for % is %', z.name, z.min_order;
  end if;
  return jsonb_build_object('order_no', o.order_no, 'track_token', o.track_token, 'status', o.status);
end $$;

create or replace function biz.public_order(p_token text)
returns jsonb language sql stable security definer set search_path = biz, public as $$
  select jsonb_build_object(
    'business', t.name, 'currency', t.base_currency, 'order_no', o.order_no, 'status', o.status, 'fulfilment', o.fulfilment,
    'table', (select name from dining_tables where id = o.table_id),
    'created_at', o.created_at, 'accepted_at', o.accepted_at, 'ready_at', o.ready_at, 'dispatched_at', o.dispatched_at,
    'delivered_at', o.delivered_at, 'completed_at', o.completed_at, 'cancelled_at', o.cancelled_at, 'cancel_reason', o.cancel_reason,
    'scheduled_for', o.scheduled_for, 'items_total', o.items_total, 'delivery_fee', o.delivery_fee, 'service_charge_pct', o.service_charge_pct,
    'prep_minutes', s.prep_minutes,
    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', i.name, 'qty', i.qty, 'status', i.status,
                'price', i.unit_price + i.modifiers_total,
                'options', (select string_agg(m->>'name', ', ') from jsonb_array_elements(i.modifiers) m)) order by i.created_at), '[]')
              from order_items i where i.order_id = o.id and i.status <> 'void'))
  from orders o join tenants t on t.id = o.tenant_id left join ext_settings s on s.tenant_id = o.tenant_id
  where o.track_token = p_token and length(p_token) >= 32;
$$;

-- ===== Bookings =====
-- Free start times for a service (any resource that offers it) or a table for a party, on a local date
create or replace function biz.booking_slots(p_outlet uuid, p_date date, p_service uuid default null, p_party int default 2)
returns table (slot timestamptz, resource_id uuid, table_id uuid)
language plpgsql stable security definer set search_path = biz, public as $$
declare st ext_settings; v_tenant uuid; tz text; dur interval; step interval; h record; t timestamptz; svc booking_services; earliest timestamptz;
begin
  select tenant_id into v_tenant from outlets where id = p_outlet;
  select * into st from ext_settings where tenant_id = v_tenant;
  tz := tenant_tz(v_tenant, p_outlet);
  step := make_interval(mins => coalesce(st.booking_slot_minutes, 15));
  earliest := now() + make_interval(mins => coalesce(st.booking_min_notice_minutes, 60));
  if p_service is not null then
    select * into svc from booking_services where id = p_service and tenant_id = v_tenant and active;
    if not found then raise exception 'Unknown service'; end if;
    dur := make_interval(mins => svc.duration_minutes + svc.buffer_minutes);
  else
    dur := make_interval(mins => coalesce(st.table_booking_minutes, 90));
  end if;
  for h in select opens, closes from business_hours where outlet_id = p_outlet and weekday = extract(isodow from p_date)::int order by opens loop
    t := (p_date + h.opens) at time zone tz;
    while t + case when p_service is null then interval '60 minutes' else dur end <= (p_date + h.closes) at time zone tz loop
      if t >= earliest then
        if p_service is not null then
          return query
            select t, r.id, null::uuid from booking_resources r join resource_services rs on rs.resource_id = r.id and rs.service_id = p_service
            where r.outlet_id = p_outlet and r.active
              and not exists (select 1 from bookings b where b.resource_id = r.id and b.status in ('pending','confirmed','arrived')
                              and tstzrange(b.start_at, b.end_at) && tstzrange(t, t + dur))
            order by r.name limit 1;
        else
          return query
            select t, null::uuid, d.id from dining_tables d
            where d.outlet_id = p_outlet and d.active and d.bookable and d.seats >= p_party
              and not exists (select 1 from bookings b where b.table_id = d.id and b.status in ('pending','confirmed','arrived')
                              and tstzrange(b.start_at, b.end_at) && tstzrange(t, t + dur))
            order by d.seats, d.name limit 1;
        end if;
      end if;
      t := t + step;
    end loop;
  end loop;
end $$;

create or replace function biz.booking_insert(p_outlet uuid, p_kind text, p_service uuid, p_resource uuid, p_table uuid, p_start timestamptz,
                                                 p_party int, p_name text, p_phone text, p_email text, p_notes text, p_source text, p_status text)
returns bookings language plpgsql security definer set search_path = biz, public as $$
declare v_tenant uuid; st ext_settings; svc booking_services; v_end timestamptz; b bookings; biz text; tz text; base text;
begin
  select tenant_id into v_tenant from outlets where id = p_outlet;
  select * into st from ext_settings where tenant_id = v_tenant;
  if coalesce(length(trim(p_name)), 0) < 2 then raise exception 'Enter a name'; end if;
  if p_party < 1 or p_party > coalesce(st.booking_max_party, 12) then raise exception 'For groups over %, please call us', st.booking_max_party; end if;
  if p_kind = 'service' then
    select * into svc from booking_services where id = p_service and tenant_id = v_tenant and active;
    if not found then raise exception 'Choose a service'; end if;
    if p_resource is null or not exists (select 1 from resource_services where resource_id = p_resource and service_id = p_service) then
      raise exception 'Choose who or where';
    end if;
    v_end := p_start + make_interval(mins => svc.duration_minutes + svc.buffer_minutes);
  else
    if p_table is not null and not exists (select 1 from dining_tables where id = p_table and outlet_id = p_outlet and seats >= p_party) then
      raise exception 'That table is too small';
    end if;
    v_end := p_start + make_interval(mins => coalesce(st.table_booking_minutes, 90));
  end if;
  begin
    insert into bookings (tenant_id, outlet_id, kind, service_id, resource_id, table_id, contact_id, name, phone, email, party_size,
                          start_at, end_at, status, source, notes)
    values (v_tenant, p_outlet, p_kind, case when p_kind = 'service' then p_service end, case when p_kind = 'service' then p_resource end,
            case when p_kind = 'table' then p_table end, contact_for(v_tenant, p_name, p_phone, p_email, 'booking'),
            left(trim(p_name), 80), left(nullif(trim(p_phone), ''), 30), lower(left(nullif(trim(p_email), ''), 120)), p_party,
            p_start, v_end, p_status, p_source, left(nullif(trim(p_notes), ''), 500))
    returning * into b;
  exception when exclusion_violation then
    raise exception 'Sorry, that time was just taken — please choose another';
  end;
  if b.phone is not null or b.email is not null then
    select name into biz from tenants where id = v_tenant;
    tz := tenant_tz(v_tenant, p_outlet);
    base := st.web_base_url;
    insert into outbound_messages (tenant_id, channel, to_address, subject, body)
    values (v_tenant, case when b.email is not null then 'email' else 'whatsapp' end, coalesce(b.email, norm_phone(b.phone)),
            biz || ' booking', 'Hi ' || split_part(b.name, ' ', 1) || ', your booking at ' || biz || ' is '
            || case when b.status = 'pending' then 'requested' else 'confirmed' end || ' for '
            || to_char(b.start_at at time zone tz, 'Dy DD Mon, HH24:MI')
            || coalesce(' — ' || svc.name, ' for ' || b.party_size || case when b.party_size = 1 then ' person' else ' people' end) || '.'
            || case when base is not null then ' Change or cancel: ' || rtrim(base, '/') || '/book.html?b=' || b.token else '' end);
  end if;
  return b;
end $$;

create or replace function biz.create_booking(p_outlet uuid, p_kind text, p_start timestamptz, p_party int, p_name text,
                                                 p_phone text default null, p_email text default null, p_service uuid default null,
                                                 p_resource uuid default null, p_table uuid default null, p_notes text default null)
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare v_tenant uuid; b bookings; s record;
begin
  select tenant_id into v_tenant from outlets where id = p_outlet;
  if not has_perm(v_tenant, 'book.manage') then raise exception 'Not allowed'; end if;
  -- staff may leave the resource/table empty: take the first free one
  if p_kind = 'service' and p_resource is null then
    select * into s from booking_slots(p_outlet, (p_start at time zone tenant_tz(v_tenant, p_outlet))::date, p_service, p_party) x where x.slot = p_start limit 1;
    p_resource := s.resource_id;
    if p_resource is null then raise exception 'Nobody is free at that time'; end if;
  elsif p_kind = 'table' and p_table is null then
    select * into s from booking_slots(p_outlet, (p_start at time zone tenant_tz(v_tenant, p_outlet))::date, null, p_party) x where x.slot = p_start limit 1;
    p_table := s.table_id;      -- may stay empty for a request without a table
  end if;
  b := booking_insert(p_outlet, p_kind, p_service, p_resource, p_table, p_start, p_party, p_name, p_phone, p_email, p_notes, 'staff', 'confirmed');
  return b.id;
end $$;

create or replace function biz.set_booking_status(p_booking uuid, p_status text)
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare b bookings; oid uuid;
begin
  select * into b from bookings where id = p_booking for update;
  if not found or not has_perm(b.tenant_id, 'book.manage') then raise exception 'Not allowed'; end if;
  if p_status not in ('confirmed','arrived','completed','no_show','cancelled') then raise exception 'Unknown status'; end if;
  if b.status in ('completed','cancelled') then raise exception 'Booking is %', b.status; end if;
  update bookings set status = p_status where id = b.id;
  -- seating a table booking opens the table's order
  if p_status = 'arrived' and b.kind = 'table' and b.table_id is not null and has_perm(b.tenant_id, 'ord.take') then
    oid := open_order(b.outlet_id, 'dine_in', b.table_id, b.party_size, jsonb_build_object('name', b.name, 'phone', b.phone, 'email', b.email));
    update bookings set order_id = oid where id = b.id;
  end if;
  return oid;
end $$;

-- The product sold for a service (created on first use)
create or replace function biz.service_variant(p_service uuid)
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare svc booking_services; pid uuid; vid uuid;
begin
  select * into svc from booking_services where id = p_service;
  if svc.variant_id is not null then return svc.variant_id; end if;
  insert into products (tenant_id, name, kind, on_menu) values (svc.tenant_id, svc.name, 'service', false) returning id into pid;
  insert into product_variants (tenant_id, product_id, sku, price, track_stock)
  values (svc.tenant_id, pid, 'SVC-' || upper(substr(replace(svc.id::text, '-', ''), 1, 8)), svc.price, false) returning id into vid;
  update booking_services set variant_id = vid where id = svc.id;
  return vid;
end $$;

create or replace function biz.booking_quote(p_booking uuid)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare b bookings; svc booking_services; vid uuid; t record; v_net numeric; v_tax numeric;
begin
  select * into b from bookings where id = p_booking;
  if not found or not has_perm(b.tenant_id, 'book.manage') then raise exception 'Not allowed'; end if;
  if b.kind <> 'service' then raise exception 'Table bookings are paid through their order'; end if;
  select * into svc from booking_services where id = b.service_id;
  vid := service_variant(svc.id);
  select r.* into t from product_variants v join products p on p.id = v.product_id,
       lateral resolve_tax(b.tenant_id, b.outlet_id, p.tax_code, current_date) r where v.id = vid;
  v_net := svc.price;
  if coalesce(t.inclusive, false) then v_tax := round(v_net - v_net / (1 + coalesce(t.rate, 0)), 2);
  else v_tax := round(v_net * coalesce(t.rate, 0), 2); v_net := v_net + v_tax; end if;
  return jsonb_build_object('name', svc.name, 'price', svc.price, 'tax', v_tax, 'total', v_net);
end $$;

-- Service booking checkout through the POS
create or replace function biz.checkout_booking(p_booking uuid, p_payments jsonb, p_shift uuid default null, p_client_sale_id uuid default null)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare b bookings; svc booking_services; vid uuid; v_sale sales;
begin
  select * into b from bookings where id = p_booking for update;
  if not found or not has_perm(b.tenant_id, 'book.manage') then raise exception 'Not allowed'; end if;
  if b.kind <> 'service' then raise exception 'Table bookings are paid through their order'; end if;
  if b.status in ('completed','cancelled','no_show') then raise exception 'Booking is %', b.status; end if;
  select * into svc from booking_services where id = b.service_id;
  vid := service_variant(svc.id);
  v_sale := complete_sale(jsonb_build_object('outlet_id', b.outlet_id, 'shift_id', p_shift,
    'client_sale_id', coalesce(p_client_sale_id, gen_random_uuid()), 'customer_id', b.contact_id,
    'lines', jsonb_build_array(jsonb_build_object('variant_id', vid, 'qty', 1, 'unit_price', svc.price)),
    'payments', p_payments, 'note', 'Booking ' || svc.name || ' · ' || b.name));
  update bookings set status = 'completed', sale_id = v_sale.id where id = b.id;
  return jsonb_build_object('sale_id', v_sale.id, 'receipt_no', v_sale.receipt_no, 'total', v_sale.total);
end $$;

-- Public booking page
create or replace function biz.public_booking_options(p_key text)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare k record; st ext_settings;
begin
  select * into k from resolve_public_key(p_key);
  select * into st from ext_settings where tenant_id = k.tenant_id;
  if not st.booking_enabled then raise exception 'Online booking is not available'; end if;
  return jsonb_build_object(
    'business', (select name from tenants where id = k.tenant_id), 'outlet', (select name from outlets where id = k.outlet_id),
    'currency', (select base_currency from tenants where id = k.tenant_id),
    'tables', exists (select 1 from dining_tables where outlet_id = k.outlet_id and bookable and active),
    'max_party', st.booking_max_party, 'days_ahead', st.booking_days_ahead,
    'services', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'description', s.description,
                   'minutes', s.duration_minutes, 'price', s.price) order by s.name), '[]')
                 from booking_services s where s.tenant_id = k.tenant_id and s.active and s.online
                   and exists (select 1 from resource_services rs join booking_resources r on r.id = rs.resource_id
                               where rs.service_id = s.id and r.active and r.outlet_id = k.outlet_id)));
end $$;

create or replace function biz.public_booking_slots(p_key text, p_date date, p_service uuid default null, p_party int default 2)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare k record; st ext_settings;
begin
  select * into k from resolve_public_key(p_key);
  select * into st from ext_settings where tenant_id = k.tenant_id;
  if not st.booking_enabled then raise exception 'Online booking is not available'; end if;
  if p_date > current_date + st.booking_days_ahead then return '[]'; end if;
  return (select coalesce(jsonb_agg(to_char(x.slot at time zone tenant_tz(k.tenant_id, k.outlet_id), 'HH24:MI') order by x.slot), '[]')
          from booking_slots(k.outlet_id, p_date, p_service, p_party) x);
end $$;

create or replace function biz.public_book(p_key text, p_date date, p_time text, p_service uuid, p_party int,
                                              p_name text, p_phone text, p_email text, p_notes text)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare k record; st ext_settings; s record; v_start timestamptz; b bookings; recent int;
begin
  select * into k from resolve_public_key(p_key);
  select * into st from ext_settings where tenant_id = k.tenant_id;
  if not st.booking_enabled then raise exception 'Online booking is not available'; end if;
  if norm_phone(p_phone) is null or length(norm_phone(p_phone)) < 9 then raise exception 'Enter your phone number'; end if;
  if p_party < 1 or p_party > st.booking_max_party then raise exception 'For groups over %, please call us', st.booking_max_party; end if;
  select count(*) into recent from bookings where tenant_id = k.tenant_id and norm_phone(phone) = norm_phone(p_phone)
    and status in ('pending','confirmed') and start_at > now();
  if recent >= 3 then raise exception 'You already have 3 upcoming bookings — please call us'; end if;
  v_start := (p_date + p_time::time) at time zone tenant_tz(k.tenant_id, k.outlet_id);
  select * into s from booking_slots(k.outlet_id, p_date, p_service, p_party) x where x.slot = v_start limit 1;
  if s.slot is null then raise exception 'Sorry, that time is no longer free'; end if;
  b := booking_insert(k.outlet_id, case when p_service is null then 'table' else 'service' end, p_service, s.resource_id, s.table_id,
                      v_start, p_party, p_name, p_phone, p_email, p_notes, 'web', 'confirmed');
  return jsonb_build_object('token', b.token, 'start', to_char(b.start_at at time zone tenant_tz(k.tenant_id, k.outlet_id), 'Dy DD Mon YYYY, HH24:MI'));
end $$;

create or replace function biz.public_booking(p_token text)
returns jsonb language sql stable security definer set search_path = biz, public as $$
  select jsonb_build_object('business', t.name, 'name', b.name, 'status', b.status, 'party_size', b.party_size, 'kind', b.kind,
    'service', (select name from booking_services where id = b.service_id),
    'with', (select name from booking_resources where id = b.resource_id),
    'start', to_char(b.start_at at time zone tenant_tz(b.tenant_id, b.outlet_id), 'Dy DD Mon YYYY, HH24:MI'),
    'can_cancel', b.status in ('pending','confirmed') and b.start_at > now() + interval '2 hours')
  from bookings b join tenants t on t.id = b.tenant_id
  where b.token = p_token and length(p_token) >= 32;
$$;

create or replace function biz.public_cancel_booking(p_token text)
returns void language plpgsql security definer set search_path = biz, public as $$
declare b bookings;
begin
  select * into b from bookings where token = p_token and length(p_token) >= 32 for update;
  if not found then raise exception 'Booking not found'; end if;
  if b.status not in ('pending','confirmed') then raise exception 'This booking is %', b.status; end if;
  if b.start_at <= now() + interval '2 hours' then raise exception 'Too late to cancel online — please call us'; end if;
  update bookings set status = 'cancelled', notes = coalesce(notes || E'\n', '') || 'Cancelled online by customer' where id = b.id;
end $$;

-- Reminder messages for tomorrow's bookings (run daily by cron with the service key, or from the app)
create or replace function biz.queue_booking_reminders(p_tenant uuid default null)
returns int language plpgsql security definer set search_path = biz, public as $$
declare b record; n int := 0;
begin
  if p_tenant is not null and not has_perm(p_tenant, 'book.manage') then raise exception 'Not allowed'; end if;
  if p_tenant is null and auth.uid() is not null then raise exception 'Not allowed'; end if;
  for b in select bk.*, t.name biz from bookings bk join tenants t on t.id = bk.tenant_id
           where (p_tenant is null or bk.tenant_id = p_tenant) and bk.status = 'confirmed' and bk.reminder_sent_at is null
             and bk.start_at between now() + interval '2 hours' and now() + interval '26 hours'
             and (bk.phone is not null or bk.email is not null) loop
    insert into outbound_messages (tenant_id, channel, to_address, subject, body)
    values (b.tenant_id, case when b.email is not null then 'email' else 'whatsapp' end, coalesce(b.email, norm_phone(b.phone)),
            'Reminder: ' || b.biz, 'Reminder: you are booked at ' || b.biz || ' on '
            || to_char(b.start_at at time zone tenant_tz(b.tenant_id, b.outlet_id), 'Dy DD Mon, HH24:MI') || '. See you soon!');
    update bookings set reminder_sent_at = now() where id = b.id;
    n := n + 1;
  end loop;
  return n;
end $$;

-- ===== Shop sync (called by the shop-sync edge function with the service key) =====
-- Stock to publish: on hand at the channel outlet minus what open orders already promise
create or replace function biz.shop_stock_snapshot(p_tenant uuid, p_provider text)
returns table (variant_id uuid, sku text, external_id text, external_parent_id text, inventory_item_id text, available numeric, last_pushed_qty numeric)
language sql stable security definer set search_path = biz, public as $$
  select l.variant_id, v.sku, l.external_id, l.external_parent_id, l.inventory_item_id,
         greatest(0, floor(coalesce(sl.qty, 0) - coalesce((select sum(oi.qty) from order_items oi join orders o on o.id = oi.order_id
                              where oi.variant_id = l.variant_id and o.outlet_id = c.outlet_id and oi.status <> 'void'
                                and o.status in ('pending','open','ready','out_for_delivery','delivered')), 0))),
         l.last_pushed_qty
  from shop_links l join shop_channels c on c.tenant_id = l.tenant_id and c.provider = l.provider
  join product_variants v on v.id = l.variant_id
  left join stock_levels sl on sl.variant_id = l.variant_id and sl.outlet_id = c.outlet_id
  where l.tenant_id = p_tenant and l.provider = p_provider and v.track_stock and auth.uid() is null;
$$;

-- p: {"external_ref","number","created_at","paid":true,"total":123.4,"currency":"MYR","shipping":10,
--     "customer":{"name","email","phone"},"address":"…","postcode":"…","note":"…","items":[{"sku","name","qty","price"}]}
create or replace function biz.shop_import_order(p_tenant uuid, p_provider text, p jsonb)
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare c shop_channels; oid uuid; it jsonb; v product_variants; n int := 0;
begin
  if auth.uid() is not null then raise exception 'Not allowed'; end if;     -- service key only
  select * into c from shop_channels where tenant_id = p_tenant and provider = p_provider;
  if not found then raise exception 'Channel not set up'; end if;
  select id into oid from orders where tenant_id = p_tenant and external_provider = p_provider and external_ref = p->>'external_ref';
  if oid is not null then return oid; end if;
  insert into orders (tenant_id, outlet_id, order_no, channel, source, status, contact_id, customer_name, customer_phone, customer_email,
                      notes, fulfilment, delivery_address, delivery_postcode, delivery_fee, external_provider, external_ref,
                      prepaid, prepaid_amount, created_at, created_by)
  values (p_tenant, c.outlet_id, next_order_no(c.outlet_id), 'online', p_provider, 'pending',
          contact_for(p_tenant, p->'customer'->>'name', p->'customer'->>'phone', p->'customer'->>'email', p_provider),
          left(p->'customer'->>'name', 80), left(p->'customer'->>'phone', 30), lower(left(p->'customer'->>'email', 120)),
          left(concat_ws(' · ', p_provider || ' ' || coalesce(p->>'number', p->>'external_ref'), nullif(p->>'note', '')), 500),
          case when nullif(p->>'address', '') is null then 'pickup' else 'shipping' end,
          left(p->>'address', 300), left(p->>'postcode', 10), coalesce((p->>'shipping')::numeric, 0), p_provider, p->>'external_ref',
          coalesce((p->>'paid')::boolean, false), (p->>'total')::numeric, coalesce((p->>'created_at')::timestamptz, now()), null)
  returning id into oid;
  for it in select * from jsonb_array_elements(coalesce(p->'items', '[]')) loop
    select * into v from product_variants where tenant_id = p_tenant and sku = it->>'sku' and coalesce(it->>'sku', '') <> '';
    insert into order_items (tenant_id, order_id, variant_id, name, qty, unit_price, status, source, created_by)
    values (p_tenant, oid, v.id, left(coalesce(it->>'name', it->>'sku', 'Item'), 200), greatest((it->>'qty')::numeric, 1),
            coalesce((it->>'price')::numeric, 0), 'new', p_provider, null);
    n := n + 1;
  end loop;
  -- shipping charged by the shop goes on the sale as the delivery fee
  return oid;
end $$;

create or replace function biz.set_shop_secret(p_tenant uuid, p_provider text, p_config jsonb, p_outlet uuid)
returns void language plpgsql security definer set search_path = biz, public as $$
begin
  if not has_perm(p_tenant, 'ord.settings') then raise exception 'Not allowed'; end if;
  if p_provider not in ('shopify','woocommerce') then raise exception 'Unknown shop'; end if;
  if not exists (select 1 from outlets where id = p_outlet and tenant_id = p_tenant) then raise exception 'Choose the outlet that holds the stock'; end if;
  if p_provider = 'shopify' and (coalesce(p_config->>'shop_domain', '') !~ '^[a-z0-9-]+\.myshopify\.com$' or coalesce(p_config->>'access_token', '') = '') then
    raise exception 'Enter your-shop.myshopify.com and the Admin API access token';
  end if;
  if p_provider = 'woocommerce' and (coalesce(p_config->>'base_url', '') !~ '^https://' or coalesce(p_config->>'consumer_key', '') = ''
     or coalesce(p_config->>'consumer_secret', '') = '') then
    raise exception 'Enter the https:// shop address, consumer key and consumer secret';
  end if;
  insert into integration_secrets (tenant_id, provider, config) values (p_tenant, p_provider, p_config)
  on conflict (tenant_id, provider) do update set config = excluded.config, updated_at = now();
  insert into shop_channels (tenant_id, provider, outlet_id) values (p_tenant, p_provider, p_outlet)
  on conflict (tenant_id, provider) do update set outlet_id = excluded.outlet_id, enabled = true, last_error = null;
end $$;

-- ===== RLS =====
alter table biz.ext_settings enable row level security;
create policy exs_read on biz.ext_settings for select using (is_member(tenant_id));
create policy exs_write on biz.ext_settings for update using (has_perm(tenant_id, 'ord.settings')) with check (has_perm(tenant_id, 'ord.settings'));

do $$ declare t text; begin
  foreach t in array array['business_hours','dining_areas','dining_tables','kitchen_stations','modifier_groups','modifiers',
                           'product_modifier_groups','delivery_zones','booking_services','booking_resources','resource_services'] loop
    execute format('alter table biz.%I enable row level security', t);
    execute format('create policy %1$s_read on biz.%1$I for select using (is_member(tenant_id))', t);
    execute format('create policy %1$s_write on biz.%1$I for all using (has_perm(tenant_id, ''ord.settings'')) with check (has_perm(tenant_id, ''ord.settings''))', t);
  end loop;
end $$;

alter table biz.order_counters enable row level security;

alter table biz.orders enable row level security;
create policy orders_read on biz.orders for select using (has_perm(tenant_id, 'ord.view') or has_perm(tenant_id, 'pos.sale.create')
  or (rider_id = auth.uid() and has_perm(tenant_id, 'ord.deliver')));
create policy orders_notes on biz.orders for update using (has_perm(tenant_id, 'ord.take')) with check (has_perm(tenant_id, 'ord.take'));

-- only notes/guests/customer fields may be edited directly; everything else goes through the functions
create or replace function biz.orders_guard()
returns trigger language plpgsql as $$
begin
  if current_user in ('authenticated','anon') and (
       new.status is distinct from old.status or new.items_total is distinct from old.items_total or new.sale_id is distinct from old.sale_id
    or new.table_id is distinct from old.table_id or new.tenant_id is distinct from old.tenant_id or new.rider_id is distinct from old.rider_id
    or new.prepaid is distinct from old.prepaid or new.track_token is distinct from old.track_token or new.order_no is distinct from old.order_no) then
    raise exception 'Use the order actions to change that';
  end if;
  return new;
end $$;
create trigger trg_orders_guard before update on biz.orders for each row execute function biz.orders_guard();

alter table biz.order_items enable row level security;
create policy oitems_read on biz.order_items for select using (has_perm(tenant_id, 'ord.view') or has_perm(tenant_id, 'pos.sale.create')
  or exists (select 1 from orders o where o.id = order_id and o.rider_id = auth.uid()));

alter table biz.bookings enable row level security;
create policy bookings_read on biz.bookings for select using (has_perm(tenant_id, 'book.view') or has_perm(tenant_id, 'book.manage'));
create policy bookings_notes on biz.bookings for update using (has_perm(tenant_id, 'book.manage')) with check (has_perm(tenant_id, 'book.manage'));

create or replace function biz.bookings_guard()
returns trigger language plpgsql as $$
begin
  if current_user in ('authenticated','anon') and (new.status is distinct from old.status or new.start_at is distinct from old.start_at
     or new.end_at is distinct from old.end_at or new.token is distinct from old.token or new.sale_id is distinct from old.sale_id
     or new.tenant_id is distinct from old.tenant_id) then
    raise exception 'Use the booking actions to change that';
  end if;
  return new;
end $$;
create trigger trg_bookings_guard before update on biz.bookings for each row execute function biz.bookings_guard();

alter table biz.shop_channels enable row level security;
create policy shopch_read on biz.shop_channels for select using (has_perm(tenant_id, 'ord.settings'));
create policy shopch_write on biz.shop_channels for update using (has_perm(tenant_id, 'ord.settings')) with check (has_perm(tenant_id, 'ord.settings'));
alter table biz.shop_links enable row level security;
create policy shoplinks_read on biz.shop_links for select using (has_perm(tenant_id, 'ord.settings'));

create or replace function biz.rotate_table_qr(p_table uuid)
returns void language plpgsql security definer set search_path = biz, public as $$
declare t dining_tables;
begin
  select * into t from dining_tables where id = p_table;
  if not found or not has_perm(t.tenant_id, 'ord.settings') then raise exception 'Not allowed'; end if;
  update dining_tables set qr_token = encode(sha256(convert_to(gen_random_uuid()::text || clock_timestamp()::text, 'UTF8')), 'hex') where id = t.id;
end $$;

-- Staff may "86" items and set menu fields without full product rights
create or replace function biz.set_menu_flags(p_product uuid, p_sold_out boolean default null, p_on_menu boolean default null, p_station uuid default null)
returns void language plpgsql security definer set search_path = biz, public as $$
declare p products;
begin
  select * into p from products where id = p_product;
  if not found or not (has_perm(p.tenant_id, 'ord.take') or has_perm(p.tenant_id, 'ord.settings')) then raise exception 'Not allowed'; end if;
  if (p_on_menu is not null or p_station is not null) and not has_perm(p.tenant_id, 'ord.settings') then raise exception 'Not allowed'; end if;
  update products set sold_out = coalesce(p_sold_out, sold_out), on_menu = coalesce(p_on_menu, on_menu),
    station_id = coalesce(p_station, station_id) where id = p.id;
end $$;

do $$ declare t text; begin
  foreach t in array array['orders','bookings','dining_tables','ext_settings','delivery_zones','booking_services','shop_channels'] loop
    execute format('create trigger audit_%1$s after insert or update or delete on biz.%1$I
                    for each row execute function biz.audit_trigger()', t);
  end loop;
end $$;

-- Public RPCs: callable without login; everything else stays for signed-in users
do $$ declare f text; begin
  foreach f in array array['public_menu(text)','public_place_order(text, jsonb, jsonb)','public_order(text)',
                           'public_booking_options(text)','public_booking_slots(text, date, uuid, integer)',
                           'public_book(text, date, text, uuid, integer, text, text, text, text)',
                           'public_booking(text)','public_cancel_booking(text)'] loop
    execute format('grant execute on function biz.%s to anon, authenticated', f);
  end loop;
end $$;


-- =====================================================================================================================
-- 0011_ai.sql (converted to schema biz)
-- =====================================================================================================================
-- Ai buddy Biz — Batch J: AI agents across modules (module AI)
-- A business assistant that reads your own numbers (only what the user's role may see), a daily briefing,
-- and agents that PROPOSE actions — draft purchase orders, follow-up messages, tasks, price changes.
-- Nothing is done until a person with the right permission approves it.
-- Depends on 0001–0010.

insert into biz.permissions (code, module, description) values
  ('ai.use','AI','Ask the AI business assistant and see its suggestions'),
  ('ai.settings','AI','AI briefing and agent settings');

insert into biz.role_permissions (role_id, permission_code)
select r.id, c from biz.roles r, unnest(array['ai.use','ai.settings']) c
where r.tenant_id is null and r.name in ('Owner','Admin') on conflict do nothing;
insert into biz.role_permissions (role_id, permission_code)
select r.id, 'ai.use' from biz.roles r
where r.tenant_id is null and r.name in ('Manager','Accountant','HR','Sales','Legal','Operations') on conflict do nothing;

-- ===== Settings & records =====
create table biz.ai_settings (
  tenant_id uuid primary key references biz.tenants(id) on delete cascade,
  daily_briefing boolean not null default false,
  briefing_hour int not null default 8 check (briefing_hour between 0 and 23),
  email_briefing boolean not null default true,        -- email it to owners & admins
  agents jsonb not null default '{"reorder":true,"collections":true,"leads":true,"customers":true,"compliance":true,"pricing":false}',
  max_price_change_pct numeric(5,2) not null default 20,
  updated_at timestamptz not null default now()
);

create table biz.ai_conversations (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references biz.tenants(id) on delete cascade,
  user_id uuid not null default auth.uid(),
  title text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table biz.ai_messages (
  id bigint generated always as identity primary key,
  tenant_id uuid not null references biz.tenants(id) on delete cascade,
  conversation_id uuid not null references biz.ai_conversations(id) on delete cascade,
  role text not null check (role in ('user','assistant')),
  content text not null,
  tools_used text[] not null default '{}',
  created_at timestamptz not null default now()
);
create index on biz.ai_messages (conversation_id, id);

create table biz.ai_suggestions (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references biz.tenants(id) on delete cascade,
  agent text not null check (agent in ('assistant','reorder','collections','leads','customers','compliance','pricing','briefing')),
  kind text not null check (kind in ('purchase_order','send_message','create_task','price_change','note')),
  title text not null,
  reason text,
  payload jsonb not null default '{}',
  status text not null default 'pending' check (status in ('pending','approved','rejected','failed','expired')),
  conversation_id uuid references biz.ai_conversations(id) on delete set null,
  created_for uuid,                      -- the user who asked (assistant), null = for the business
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '7 days',
  decided_by uuid,
  decided_at timestamptz,
  result jsonb,
  error text
);
create index on biz.ai_suggestions (tenant_id, status, created_at desc);

create table biz.ai_briefings (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references biz.tenants(id) on delete cascade,
  for_date date not null,
  content jsonb not null,               -- {headline, sections:[{title, points[]}], watch[]}
  model text,
  created_at timestamptz not null default now(),
  unique (tenant_id, for_date)
);

-- ===== Access helper: signed-in users need the permission; the server (service key / cron) may read all =====
create or replace function biz.ai_can(p_tenant uuid, p_perm text)
returns boolean language sql stable security definer set search_path = biz, public as $$
  select auth.uid() is null or has_perm(p_tenant, p_perm);
$$;

create or replace function biz.ai_local_today(p_tenant uuid)
returns date language sql stable as $$ select (now() at time zone tenant_tz(p_tenant))::date $$;

-- ===== Read tools (each returns JSON the assistant can read) =====
create or replace function biz.ai_tool_sales(p_tenant uuid, p_from date default null, p_to date default null)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare f date; t date; tz text := tenant_tz(p_tenant); days int; cur jsonb; prev jsonb;
begin
  if not (ai_can(p_tenant, 'pos.report.view') or ai_can(p_tenant, 'fin.report.view')) then return jsonb_build_object('error', 'not allowed'); end if;
  t := coalesce(p_to, ai_local_today(p_tenant));
  f := coalesce(p_from, t - 6);
  if t - f > 366 then f := t - 366; end if;
  days := t - f + 1;
  select jsonb_build_object('sales', count(*), 'revenue', coalesce(sum(total), 0), 'tax', coalesce(sum(tax_total), 0),
                            'avg_sale', round(coalesce(avg(total), 0), 2))
    into cur from sales where tenant_id = p_tenant and status = 'completed' and (sold_at at time zone tz)::date between f and t;
  select jsonb_build_object('sales', count(*), 'revenue', coalesce(sum(total), 0))
    into prev from sales where tenant_id = p_tenant and status = 'completed' and (sold_at at time zone tz)::date between f - days and f - 1;
  return jsonb_build_object(
    'period', jsonb_build_object('from', f, 'to', t, 'days', days), 'currency', (select base_currency from tenants where id = p_tenant),
    'totals', cur, 'previous_period', prev,
    'by_day', (select coalesce(jsonb_agg(x order by x->>'day'), '[]') from (
                 select jsonb_build_object('day', (sold_at at time zone tz)::date, 'revenue', sum(total), 'sales', count(*)) x
                 from sales where tenant_id = p_tenant and status = 'completed' and (sold_at at time zone tz)::date between f and t
                 group by (sold_at at time zone tz)::date) d),
    'top_products', (select coalesce(jsonb_agg(x), '[]') from (
                 select jsonb_build_object('name', sl.name, 'qty', sum(sl.qty), 'revenue', sum(sl.line_total)) x
                 from sale_lines sl join sales s on s.id = sl.sale_id
                 where s.tenant_id = p_tenant and s.status = 'completed' and (s.sold_at at time zone tz)::date between f and t
                 group by sl.name order by sum(sl.line_total) desc limit 10) d),
    'by_outlet', (select coalesce(jsonb_agg(x), '[]') from (
                 select jsonb_build_object('outlet', o.name, 'revenue', sum(s.total)) x
                 from sales s join outlets o on o.id = s.outlet_id
                 where s.tenant_id = p_tenant and s.status = 'completed' and (s.sold_at at time zone tz)::date between f and t
                 group by o.name order by sum(s.total) desc) d),
    'by_payment', (select coalesce(jsonb_agg(x), '[]') from (
                 select jsonb_build_object('method', p.method, 'amount', sum(p.amount)) x
                 from payments p join sales s on s.id = p.sale_id
                 where s.tenant_id = p_tenant and s.status = 'completed' and (s.sold_at at time zone tz)::date between f and t
                 group by p.method order by sum(p.amount) desc) d),
    'by_hour', (select coalesce(jsonb_agg(x order by (x->>'hour')::int), '[]') from (
                 select jsonb_build_object('hour', extract(hour from s.sold_at at time zone tz)::int, 'revenue', sum(s.total)) x
                 from sales s where s.tenant_id = p_tenant and s.status = 'completed' and (s.sold_at at time zone tz)::date between f and t
                 group by extract(hour from s.sold_at at time zone tz)::int) d));
end $$;

-- Low stock with sales speed and a suggested order (cover p_days days of sales at the recent rate)
create or replace function biz.ai_tool_stock(p_tenant uuid, p_days int default 14)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
begin
  if not ai_can(p_tenant, 'inv.product.view') then return jsonb_build_object('error', 'not allowed'); end if;
  return jsonb_build_object('cover_days', p_days, 'items', (select coalesce(jsonb_agg(x order by (x->>'days_left')::numeric nulls last), '[]') from (
    select jsonb_build_object(
      'variant_id', v.id, 'sku', v.sku, 'name', p.name || coalesce(' — ' || v.name, ''), 'outlet_id', sl.outlet_id, 'outlet', o.name,
      'on_hand', sl.qty, 'reorder_point', sl.reorder_point,
      'sold_per_day', round(coalesce(r.sold, 0) / 28.0, 2),
      'days_left', case when coalesce(r.sold, 0) > 0 then round(sl.qty / (r.sold / 28.0), 1) end,
      'suggested_qty', greatest(0, ceil(coalesce(r.sold, 0) / 28.0 * p_days + coalesce(sl.reorder_point, 0) - sl.qty)),
      'last_supplier_id', lp.supplier_id, 'last_supplier', lp.supplier, 'last_cost', coalesce(lp.unit_cost, v.cost),
      'lead_time_days', lp.lead_time_days) x
    from stock_levels sl
    join product_variants v on v.id = sl.variant_id and v.active and v.track_stock
    join products p on p.id = v.product_id and p.active
    join outlets o on o.id = sl.outlet_id
    left join lateral (select -sum(m.qty_change) sold from stock_movements m
                       where m.variant_id = v.id and m.outlet_id = sl.outlet_id and m.reason = 'sale' and m.at > now() - interval '28 days') r on true
    left join lateral (select po.supplier_id, su.name supplier, l.unit_cost, su.lead_time_days from purchase_order_lines l
                       join purchase_orders po on po.id = l.po_id join suppliers su on su.id = po.supplier_id
                       where l.variant_id = v.id and po.status <> 'cancelled' order by po.created_at desc limit 1) lp on true
    where sl.tenant_id = p_tenant
      and ((sl.reorder_point is not null and sl.qty <= sl.reorder_point)
           or (coalesce(r.sold, 0) > 0 and sl.qty / (r.sold / 28.0) < greatest(p_days, coalesce(lp.lead_time_days, 0) + 3)))
    limit 60) d));
end $$;

create or replace function biz.ai_tool_receivables(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare today date := ai_local_today(p_tenant);
begin
  if not ai_can(p_tenant, 'fin.invoice.view') then return jsonb_build_object('error', 'not allowed'); end if;
  return jsonb_build_object(
    'total_outstanding', (select coalesce(sum(total - amount_paid), 0) from invoices where tenant_id = p_tenant and status in ('issued','partial')),
    'total_overdue', (select coalesce(sum(total - amount_paid), 0) from invoices where tenant_id = p_tenant and status in ('issued','partial') and due_date < today),
    'overdue', (select coalesce(jsonb_agg(x order by (x->>'days_overdue')::int desc), '[]') from (
      select jsonb_build_object('invoice_id', i.id, 'number', i.number, 'contact_id', i.contact_id, 'customer', c.name,
        'has_email', c.email is not null, 'has_phone', c.phone is not null,
        'balance', i.total - i.amount_paid, 'due_date', i.due_date, 'days_overdue', today - i.due_date,
        'last_reminder', (select max(m.created_at) from outbound_messages m where m.tenant_id = p_tenant and m.contact_id = i.contact_id
                          and m.subject ilike '%' || i.number || '%')) x
      from invoices i left join contacts c on c.id = i.contact_id
      where i.tenant_id = p_tenant and i.status in ('issued','partial') and i.due_date < today
      order by today - i.due_date desc limit 40) d));
end $$;

create or replace function biz.ai_tool_pipeline(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
begin
  if not ai_can(p_tenant, 'crm.deal.view') then return jsonb_build_object('error', 'not allowed'); end if;
  return jsonb_build_object(
    'by_stage', (select coalesce(jsonb_agg(x), '[]') from (
      select jsonb_build_object('stage', st.name, 'deals', count(d.id), 'value', coalesce(sum(d.value), 0)) x
      from pipeline_stages st join pipelines p on p.id = st.pipeline_id
      left join deals d on d.stage_id = st.id and d.status = 'open'
      where p.tenant_id = p_tenant group by st.name, st.sort_order order by st.sort_order) s),
    'won_last_30_days', (select jsonb_build_object('deals', count(*), 'value', coalesce(sum(value), 0)) from deals
                         where tenant_id = p_tenant and status = 'won' and closed_at > now() - interval '30 days'),
    'stale_deals', (select coalesce(jsonb_agg(x), '[]') from (
      select jsonb_build_object('deal_id', d.id, 'title', d.title, 'contact_id', d.contact_id, 'contact', c.name, 'value', d.value,
        'score', d.score, 'stage', st.name,
        'days_since_activity', extract(day from now() - coalesce((select max(a.created_at) from activities a where a.deal_id = d.id), d.created_at))::int) x
      from deals d join pipeline_stages st on st.id = d.stage_id left join contacts c on c.id = d.contact_id
      where d.tenant_id = p_tenant and d.status = 'open'
        and coalesce((select max(a.created_at) from activities a where a.deal_id = d.id), d.created_at) < now() - interval '7 days'
      order by d.score desc, d.value desc limit 25) s),
    'overdue_tasks', (select count(*) from activities where tenant_id = p_tenant and kind in ('task','meeting') and done_at is null and due_at < now()));
end $$;

create or replace function biz.ai_tool_customers(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
begin
  if not ai_can(p_tenant, 'crm.contact.view') then return jsonb_build_object('error', 'not allowed'); end if;
  return jsonb_build_object(
    'customers', (select count(*) from contacts where tenant_id = p_tenant and lifecycle = 'customer'),
    'new_last_30_days', (select count(*) from contacts where tenant_id = p_tenant and created_at > now() - interval '30 days'),
    'top_customers_90_days', (select coalesce(jsonb_agg(x), '[]') from (
      select jsonb_build_object('contact_id', c.id, 'name', c.name, 'spent', sum(s.total), 'visits', count(*)) x
      from sales s join contacts c on c.id = s.customer_id
      where s.tenant_id = p_tenant and s.status = 'completed' and s.sold_at > now() - interval '90 days'
      group by c.id, c.name order by sum(s.total) desc limit 10) d),
    'lapsed_regulars', (select coalesce(jsonb_agg(x), '[]') from (
      select jsonb_build_object('contact_id', c.id, 'name', c.name, 'visits', c.visits, 'total_spent', c.total_spent,
        'last_purchase', (c.last_purchase_at at time zone tenant_tz(p_tenant))::date, 'marketing_consent', c.marketing_consent) x
      from contacts c where c.tenant_id = p_tenant and c.visits >= 3 and c.last_purchase_at < now() - interval '45 days'
      order by c.total_spent desc limit 20) d),
    'birthdays_next_14_days', (select coalesce(jsonb_agg(jsonb_build_object('contact_id', c.id, 'name', c.name, 'birthday', to_char(c.birthday, 'DD Mon'),
        'marketing_consent', c.marketing_consent)), '[]')
      from contacts c where c.tenant_id = p_tenant and c.birthday is not null
        and to_char(c.birthday, 'MMDD') in (select to_char(d, 'MMDD') from generate_series(current_date, current_date + 14, interval '1 day') d)));
end $$;

create or replace function biz.ai_tool_staff(p_tenant uuid, p_day date default null)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare d date := coalesce(p_day, ai_local_today(p_tenant));
begin
  if not ai_can(p_tenant, 'hr.employee.view') then return jsonb_build_object('error', 'not allowed'); end if;
  return jsonb_build_object('day', d,
    'active_staff', (select count(*) from employees where tenant_id = p_tenant and status = 'active'),
    'clocked_in', (select count(*) from attendance where tenant_id = p_tenant and work_date = d and clock_in is not null),
    'late', (select coalesce(jsonb_agg(jsonb_build_object('name', e.full_name, 'minutes_late', a.late_minutes)), '[]')
             from attendance a join employees e on e.id = a.employee_id where a.tenant_id = p_tenant and a.work_date = d and a.late_minutes > 0),
    'on_leave', (select coalesce(jsonb_agg(jsonb_build_object('name', e.full_name, 'type', lt.name)), '[]')
                 from leave_requests lr join employees e on e.id = lr.employee_id join leave_types lt on lt.id = lr.leave_type_id
                 where lr.tenant_id = p_tenant and lr.status = 'approved' and d between lr.start_date and lr.end_date),
    'pending_leave', (select count(*) from leave_requests where tenant_id = p_tenant and status = 'pending'),
    'pending_claims', (select count(*) from claims where tenant_id = p_tenant and status = 'pending'));
end $$;

create or replace function biz.ai_tool_operations(p_tenant uuid, p_day date default null)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare d date := coalesce(p_day, ai_local_today(p_tenant)); tz text := tenant_tz(p_tenant); out jsonb := '{}';
begin
  if ai_can(p_tenant, 'ord.view') then
    out := out || jsonb_build_object('orders', jsonb_build_object(
      'by_channel', (select coalesce(jsonb_object_agg(channel, n), '{}') from (select channel, count(*) n from orders
                     where tenant_id = p_tenant and (created_at at time zone tz)::date = d and status <> 'cancelled' group by channel) x),
      'cancelled', (select count(*) from orders where tenant_id = p_tenant and (created_at at time zone tz)::date = d and status = 'cancelled'),
      'open_now', (select count(*) from orders where tenant_id = p_tenant and status in ('pending','open','ready','out_for_delivery')),
      'avg_kitchen_minutes', (select round(avg(extract(epoch from ready_at - sent_at) / 60)::numeric, 1) from order_items
                              where tenant_id = p_tenant and ready_at is not null and (sent_at at time zone tz)::date = d),
      'sold_out_items', (select coalesce(jsonb_agg(name), '[]') from products where tenant_id = p_tenant and sold_out)));
  end if;
  if ai_can(p_tenant, 'book.view') then
    out := out || jsonb_build_object('bookings', jsonb_build_object(
      'today', (select count(*) from bookings where tenant_id = p_tenant and (start_at at time zone tz)::date = d and status <> 'cancelled'),
      'no_shows_last_30_days', (select count(*) from bookings where tenant_id = p_tenant and status = 'no_show' and start_at > now() - interval '30 days')));
  end if;
  if ai_can(p_tenant, 'log.shipment.view') then
    out := out || jsonb_build_object('shipments', (select coalesce(jsonb_object_agg(status, n), '{}') from (
      select status, count(*) n from shipments where tenant_id = p_tenant and status not in ('delivered','cancelled','closed') group by status) x));
  end if;
  if ai_can(p_tenant, 'kids.view') then
    out := out || jsonb_build_object('kids', jsonb_build_object(
      'enrolled', (select count(*) from children where tenant_id = p_tenant and status = 'enrolled'),
      'attended_today', (select count(*) from kids_attendance where tenant_id = p_tenant and day = d and check_in_at is not null),
      'incidents_unacknowledged', (select count(*) from kids_incidents where tenant_id = p_tenant and kind <> 'safeguarding'
                                   and parent_notified_at is not null and guardian_ack_at is null),
      'late_pickups_last_30_days', (select count(*) from kids_attendance where tenant_id = p_tenant and late_minutes > 0 and day > d - 30)));
  end if;
  return out;
end $$;

create or replace function biz.ai_tool_compliance(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare today date := ai_local_today(p_tenant);
begin
  if not ai_can(p_tenant, 'law.view') then return jsonb_build_object('error', 'not allowed'); end if;
  return jsonb_build_object(
    'overdue', (select coalesce(jsonb_agg(jsonb_build_object('title', title, 'due', due_date, 'kind', source) order by due_date), '[]')
                from legal_calendar where tenant_id = p_tenant and status = 'open' and due_date < today),
    'next_30_days', (select coalesce(jsonb_agg(jsonb_build_object('title', title, 'due', due_date, 'kind', source) order by due_date), '[]')
                     from legal_calendar where tenant_id = p_tenant and status = 'open' and due_date between today and today + 30),
    'needs_a_date', (select count(*) from compliance_items where tenant_id = p_tenant and status = 'open' and due_date is null),
    'contracts_awaiting_signature', (select count(*) from contracts where tenant_id = p_tenant and status in ('out_for_signature','partially_signed')));
end $$;

-- Search the catalog / contacts / suppliers by name (so the assistant can find ids for proposals)
create or replace function biz.ai_tool_find(p_tenant uuid, p_kind text, p_query text)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare q text := '%' || replace(replace(coalesce(p_query, ''), '%', ''), '_', '') || '%';
begin
  if p_kind = 'product' and ai_can(p_tenant, 'inv.product.view') then
    return (select coalesce(jsonb_agg(jsonb_build_object('variant_id', v.id, 'sku', v.sku, 'name', p.name || coalesce(' — ' || v.name, ''),
              'price', v.price, 'cost', v.cost)), '[]')
            from product_variants v join products p on p.id = v.product_id
            where v.tenant_id = p_tenant and v.active and (p.name ilike q or v.sku ilike q or v.name ilike q) limit 15);
  elsif p_kind = 'contact' and ai_can(p_tenant, 'crm.contact.view') then
    return (select coalesce(jsonb_agg(jsonb_build_object('contact_id', id, 'name', name, 'company', company, 'lifecycle', lifecycle,
              'has_email', email is not null, 'has_phone', phone is not null, 'marketing_consent', marketing_consent)), '[]')
            from contacts where tenant_id = p_tenant and (name ilike q or company ilike q) limit 15);
  elsif p_kind = 'supplier' and ai_can(p_tenant, 'inv.supplier.manage') then
    return (select coalesce(jsonb_agg(jsonb_build_object('supplier_id', id, 'name', name, 'lead_time_days', lead_time_days)), '[]')
            from suppliers where tenant_id = p_tenant and name ilike q limit 15);
  end if;
  return jsonb_build_object('error', 'not allowed or unknown kind');
end $$;

-- Everything the user may see, for the briefing
create or replace function biz.ai_overview(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare o jsonb; t tenants;
begin
  if not (auth.uid() is null or is_member(p_tenant)) then raise exception 'Not allowed'; end if;
  select * into t from tenants where id = p_tenant;
  o := jsonb_build_object('business', t.name, 'country', t.country_code, 'currency', t.base_currency, 'today', ai_local_today(p_tenant),
                          'modules', (select coalesce(jsonb_agg(module), '[]') from tenant_modules where tenant_id = p_tenant and enabled));
  if ai_can(p_tenant, 'pos.report.view') or ai_can(p_tenant, 'fin.report.view') then
    o := o || jsonb_build_object('sales_yesterday', ai_tool_sales(p_tenant, ai_local_today(p_tenant) - 1, ai_local_today(p_tenant) - 1) - 'by_hour' - 'by_day',
                                 'sales_last_7_days', ai_tool_sales(p_tenant, ai_local_today(p_tenant) - 7, ai_local_today(p_tenant) - 1) - 'by_hour');
  end if;
  if ai_can(p_tenant, 'inv.product.view') then o := o || jsonb_build_object('stock', ai_tool_stock(p_tenant)); end if;
  if ai_can(p_tenant, 'fin.invoice.view') then o := o || jsonb_build_object('receivables', ai_tool_receivables(p_tenant)); end if;
  if ai_can(p_tenant, 'crm.deal.view') then o := o || jsonb_build_object('pipeline', ai_tool_pipeline(p_tenant)); end if;
  if ai_can(p_tenant, 'crm.contact.view') then o := o || jsonb_build_object('customers', ai_tool_customers(p_tenant)); end if;
  if ai_can(p_tenant, 'hr.employee.view') then o := o || jsonb_build_object('staff', ai_tool_staff(p_tenant)); end if;
  if ai_can(p_tenant, 'law.view') then o := o || jsonb_build_object('compliance', ai_tool_compliance(p_tenant)); end if;
  o := o || jsonb_build_object('operations', ai_tool_operations(p_tenant));
  return o;
end $$;

-- ===== Proposals and approvals =====
create or replace function biz.ai_propose(p_tenant uuid, p_agent text, p_kind text, p_title text, p_reason text, p_payload jsonb,
                                             p_conversation uuid default null)
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare sid uuid; n int;
begin
  if not ai_can(p_tenant, 'ai.use') then raise exception 'Not allowed'; end if;
  if p_kind not in ('purchase_order','send_message','create_task','price_change','note') then raise exception 'Unknown action'; end if;
  select count(*) into n from ai_suggestions where tenant_id = p_tenant and status = 'pending';
  if n >= 200 then raise exception 'Too many suggestions waiting — review some first'; end if;
  -- avoid duplicates of the same pending idea
  select id into sid from ai_suggestions where tenant_id = p_tenant and status = 'pending' and kind = p_kind and payload = p_payload;
  if sid is not null then return sid; end if;
  insert into ai_suggestions (tenant_id, agent, kind, title, reason, payload, conversation_id, created_for)
  values (p_tenant, p_agent, p_kind, left(p_title, 200), left(p_reason, 2000), coalesce(p_payload, '{}'), p_conversation, auth.uid())
  returning id into sid;
  return sid;
end $$;

-- A person approves (optionally with edits) or rejects. Approval runs with THEIR permissions.
create or replace function biz.ai_decide(p_suggestion uuid, p_approve boolean, p_edits jsonb default null)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare sg ai_suggestions; p jsonb; res jsonb; po_id uuid; l jsonb; c contacts; v product_variants; ch text; addr text;
        st ai_settings; pct numeric; n int := 0; due timestamptz;
begin
  select * into sg from ai_suggestions where id = p_suggestion for update;
  if not found or not has_perm(sg.tenant_id, 'ai.use') then raise exception 'Not allowed'; end if;
  if sg.status <> 'pending' then raise exception 'Already %', sg.status; end if;
  if sg.expires_at < now() then
    update ai_suggestions set status = 'expired' where id = sg.id;
    raise exception 'This suggestion has expired';
  end if;
  if not p_approve then
    update ai_suggestions set status = 'rejected', decided_by = auth.uid(), decided_at = now() where id = sg.id;
    return jsonb_build_object('status', 'rejected');
  end if;
  p := sg.payload || coalesce(p_edits, '{}');

  if sg.kind = 'purchase_order' then
    if not has_perm(sg.tenant_id, 'inv.supplier.manage') then raise exception 'You need purchasing rights to approve this'; end if;
    if not exists (select 1 from suppliers where id = (p->>'supplier_id')::uuid and tenant_id = sg.tenant_id) then raise exception 'Choose a supplier'; end if;
    if not exists (select 1 from outlets where id = (p->>'outlet_id')::uuid and tenant_id = sg.tenant_id) then raise exception 'Choose an outlet'; end if;
    insert into purchase_orders (tenant_id, supplier_id, outlet_id, notes, currency)
    values (sg.tenant_id, (p->>'supplier_id')::uuid, (p->>'outlet_id')::uuid, 'Suggested by AI: ' || sg.title,
            (select base_currency from tenants where id = sg.tenant_id))
    returning id into po_id;
    for l in select * from jsonb_array_elements(coalesce(p->'lines', '[]')) loop
      select * into v from product_variants where id = (l->>'variant_id')::uuid and tenant_id = sg.tenant_id;
      if not found or coalesce((l->>'qty')::numeric, 0) <= 0 then continue; end if;
      insert into purchase_order_lines (tenant_id, po_id, variant_id, qty_ordered, unit_cost)
      values (sg.tenant_id, po_id, v.id, (l->>'qty')::numeric, coalesce((l->>'unit_cost')::numeric, v.cost));
      n := n + 1;
    end loop;
    if n = 0 then raise exception 'No valid lines to order'; end if;
    res := jsonb_build_object('purchase_order_id', po_id, 'number', (select number from purchase_orders where id = po_id), 'lines', n);

  elsif sg.kind = 'send_message' then
    if not (has_perm(sg.tenant_id, 'crm.contact.manage') or has_perm(sg.tenant_id, 'fin.invoice.manage')) then
      raise exception 'You need customer or invoicing rights to approve this';
    end if;
    -- the address always comes from the contact record, never from the AI
    select * into c from contacts where id = (p->>'contact_id')::uuid and tenant_id = sg.tenant_id;
    if not found then raise exception 'Unknown customer'; end if;
    if coalesce(p->>'purpose', 'service') = 'marketing' and not c.marketing_consent then
      raise exception '% has not agreed to marketing messages', c.name;
    end if;
    ch := case when p->>'channel' in ('email','whatsapp','sms') then p->>'channel' when c.email is not null then 'email' else 'whatsapp' end;
    addr := case ch when 'email' then lower(c.email) else norm_phone(c.phone) end;
    if addr is null then raise exception '% has no % on file', c.name, case ch when 'email' then 'email' else 'phone' end; end if;
    if coalesce(length(trim(p->>'body')), 0) < 5 then raise exception 'The message is empty'; end if;
    insert into outbound_messages (tenant_id, contact_id, channel, to_address, subject, body)
    values (sg.tenant_id, c.id, ch, addr, left(p->>'subject', 200), left(p->>'body', 2000));
    insert into activities (tenant_id, contact_id, kind, body, created_by)
    values (sg.tenant_id, c.id, case ch when 'email' then 'email' else 'whatsapp' end, 'Sent (AI draft approved): ' || left(p->>'body', 500), auth.uid());
    res := jsonb_build_object('queued_to', c.name, 'channel', ch);

  elsif sg.kind = 'create_task' then
    if not (has_perm(sg.tenant_id, 'crm.deal.manage') or has_perm(sg.tenant_id, 'crm.contact.manage')) then raise exception 'Not allowed'; end if;
    if p->>'contact_id' is null and p->>'deal_id' is null then raise exception 'A task needs a customer or deal'; end if;
    if p->>'contact_id' is not null and not exists (select 1 from contacts where id = (p->>'contact_id')::uuid and tenant_id = sg.tenant_id) then
      raise exception 'Unknown customer';
    end if;
    if p->>'deal_id' is not null and not exists (select 1 from deals where id = (p->>'deal_id')::uuid and tenant_id = sg.tenant_id) then
      raise exception 'Unknown deal';
    end if;
    due := coalesce((p->>'due_at')::timestamptz, now() + interval '1 day');
    insert into activities (tenant_id, contact_id, deal_id, kind, body, due_at, owner_id, created_by)
    values (sg.tenant_id, (p->>'contact_id')::uuid, (p->>'deal_id')::uuid, 'task', left(coalesce(p->>'body', sg.title), 1000), due, auth.uid(), auth.uid());
    res := jsonb_build_object('task_due', due);

  elsif sg.kind = 'price_change' then
    if not has_perm(sg.tenant_id, 'inv.product.manage') then raise exception 'You need product rights to approve this'; end if;
    select * into v from product_variants where id = (p->>'variant_id')::uuid and tenant_id = sg.tenant_id;
    if not found then raise exception 'Unknown product'; end if;
    select * into st from ai_settings where tenant_id = sg.tenant_id;
    if (p->>'new_price')::numeric is null or (p->>'new_price')::numeric < 0 then raise exception 'Invalid price'; end if;
    pct := case when v.price > 0 then abs((p->>'new_price')::numeric - v.price) / v.price * 100 else 100 end;
    if pct > coalesce(st.max_price_change_pct, 20) then
      raise exception 'Change of % %% is above your limit of % %% — edit the price or change it in Catalog', round(pct, 1), coalesce(st.max_price_change_pct, 20);
    end if;
    update product_variants set price = (p->>'new_price')::numeric where id = v.id;
    res := jsonb_build_object('variant_id', v.id, 'old_price', v.price, 'new_price', (p->>'new_price')::numeric);

  else
    res := jsonb_build_object('noted', true);
  end if;

  update ai_suggestions set status = 'approved', decided_by = auth.uid(), decided_at = now(), result = res,
    payload = p where id = sg.id;
  update ai_usage set confirmed = true where tenant_id = sg.tenant_id and proposed_action->>'suggestion_id' = sg.id::text;
  return jsonb_build_object('status', 'approved', 'result', res);
end $$;

-- Called by the ai-agent function to record a conversation turn and usage
create or replace function biz.ai_record(p_tenant uuid, p_conversation uuid, p_user_text text, p_reply text, p_tools text[],
                                            p_feature text, p_model text, p_in int, p_out int, p_cost numeric)
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare cid uuid := p_conversation;
begin
  if not ai_can(p_tenant, 'ai.use') then raise exception 'Not allowed'; end if;
  if p_user_text is not null then
    if cid is null or not exists (select 1 from ai_conversations where id = cid and tenant_id = p_tenant and user_id = auth.uid()) then
      insert into ai_conversations (tenant_id, user_id, title) values (p_tenant, auth.uid(), left(p_user_text, 80)) returning id into cid;
    end if;
    insert into ai_messages (tenant_id, conversation_id, role, content) values (p_tenant, cid, 'user', left(p_user_text, 8000));
    insert into ai_messages (tenant_id, conversation_id, role, content, tools_used) values (p_tenant, cid, 'assistant', left(p_reply, 20000), coalesce(p_tools, '{}'));
    update ai_conversations set updated_at = now() where id = cid;
  end if;
  insert into ai_usage (tenant_id, user_id, feature, input_tokens, output_tokens, cost_usd)
  values (p_tenant, auth.uid(), p_feature, p_in, p_out, p_cost);
  return cid;
end $$;

create or replace function biz.ai_check_quota(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare q jsonb;
begin
  if not ai_can(p_tenant, 'ai.use') then raise exception 'Not allowed to use the AI assistant'; end if;
  q := (select jsonb_build_object(
          'used', (select count(*) from ai_usage where tenant_id = p_tenant and at >= date_trunc('month', now())),
          'limit', (select monthly_requests from ai_plan_limits where plan = t.plan), 'plan', t.plan,
          'business', t.name, 'country', t.country_code, 'currency', t.base_currency,
          'today', ai_local_today(p_tenant), 'timezone', tenant_tz(p_tenant),
          'role', (select r.name from memberships m join roles r on r.id = m.role_id where m.tenant_id = p_tenant and m.user_id = auth.uid()),
          'modules', (select coalesce(jsonb_agg(module), '[]') from tenant_modules where tenant_id = p_tenant and enabled))
        from tenants t where t.id = p_tenant);
  if (q->>'used')::int >= coalesce((q->>'limit')::int, 0) then
    raise exception 'Monthly AI limit reached (% of %). Upgrade your plan for more.', q->>'used', q->>'limit';
  end if;
  return q;
end $$;

create or replace function biz.ai_save_briefing(p_tenant uuid, p_date date, p_content jsonb, p_model text)
returns uuid language plpgsql security definer set search_path = biz, public as $$
declare bid uuid; st ai_settings; u record; biz text; txt text;
begin
  if not ai_can(p_tenant, 'ai.use') then raise exception 'Not allowed'; end if;
  insert into ai_briefings (tenant_id, for_date, content, model) values (p_tenant, p_date, p_content, p_model)
  on conflict (tenant_id, for_date) do update set content = excluded.content, model = excluded.model, created_at = now()
  returning id into bid;
  select * into st from ai_settings where tenant_id = p_tenant;
  if auth.uid() is null and coalesce(st.email_briefing, false) then        -- scheduled run: email owners & admins
    select name into biz from tenants where id = p_tenant;
    txt := coalesce(p_content->>'headline', '') || E'\n\n' || coalesce((select string_agg((s->>'title') || E':\n' ||
             (select string_agg('• ' || pt, E'\n') from jsonb_array_elements_text(s->'points') pt), E'\n\n')
             from jsonb_array_elements(coalesce(p_content->'sections', '[]')) s), '')
           || E'\n\nOpen the app to review the AI suggestions.';
    for u in select distinct lower(au.email) email from memberships m join roles r on r.id = m.role_id join auth.users au on au.id = m.user_id
             where m.tenant_id = p_tenant and m.active and r.name in ('Owner','Admin') and au.email is not null loop
      insert into outbound_messages (tenant_id, channel, to_address, subject, body)
      values (p_tenant, 'email', u.email, biz || ' — daily briefing ' || to_char(p_date, 'DD Mon'), left(txt, 8000));
    end loop;
  end if;
  return bid;
end $$;

-- Businesses whose daily briefing is due now (for the cron run)
create or replace function biz.ai_briefings_due()
returns table (tenant_id uuid) language sql stable security definer set search_path = biz, public as $$
  select s.tenant_id from ai_settings s join tenant_modules m on m.tenant_id = s.tenant_id and m.module = 'AI' and m.enabled
  where s.daily_briefing and auth.uid() is null
    and extract(hour from now() at time zone tenant_tz(s.tenant_id)) >= s.briefing_hour
    and not exists (select 1 from ai_briefings b where b.tenant_id = s.tenant_id and b.for_date = ai_local_today(s.tenant_id));
$$;

-- ===== RLS =====
alter table biz.ai_settings enable row level security;
create policy ais_read on biz.ai_settings for select using (has_perm(tenant_id, 'ai.use'));
create policy ais_write on biz.ai_settings for all using (has_perm(tenant_id, 'ai.settings')) with check (has_perm(tenant_id, 'ai.settings'));

alter table biz.ai_conversations enable row level security;
create policy aic_own on biz.ai_conversations for select using (user_id = auth.uid() and has_perm(tenant_id, 'ai.use'));
create policy aic_del on biz.ai_conversations for delete using (user_id = auth.uid());

alter table biz.ai_messages enable row level security;
create policy aim_own on biz.ai_messages for select using (exists (select 1 from ai_conversations c where c.id = conversation_id and c.user_id = auth.uid()));

alter table biz.ai_suggestions enable row level security;
create policy aisg_read on biz.ai_suggestions for select using (has_perm(tenant_id, 'ai.use') and (created_for is null or created_for = auth.uid()
  or has_perm(tenant_id, 'ai.settings')));

alter table biz.ai_briefings enable row level security;
create policy aib_read on biz.ai_briefings for select using (has_perm(tenant_id, 'ai.use'));

do $$ declare t text; begin
  foreach t in array array['ai_settings','ai_suggestions'] loop
    execute format('create trigger audit_%1$s after insert or update or delete on biz.%1$I
                    for each row execute function biz.audit_trigger()', t);
  end loop;
end $$;

-- New businesses with the AI module get settings
create or replace function biz.ai_module_on()
returns trigger language plpgsql security definer set search_path = biz, public as $$
begin
  if new.module = 'AI' and new.enabled then insert into ai_settings (tenant_id) values (new.tenant_id) on conflict do nothing; end if;
  return null;
end $$;
create trigger trg_ai_module_on after insert or update on biz.tenant_modules for each row execute function biz.ai_module_on();
insert into biz.ai_settings (tenant_id) select tenant_id from biz.tenant_modules where module = 'AI' and enabled on conflict do nothing;

-- The read tools work without a login for the server only: never for anonymous web visitors
do $$ declare f text; begin
  foreach f in array array['ai_can(uuid, text)','ai_tool_sales(uuid, date, date)','ai_tool_stock(uuid, integer)','ai_tool_receivables(uuid)',
    'ai_tool_pipeline(uuid)','ai_tool_customers(uuid)','ai_tool_staff(uuid, date)','ai_tool_operations(uuid, date)','ai_tool_compliance(uuid)',
    'ai_tool_find(uuid, text, text)','ai_overview(uuid)','ai_propose(uuid, text, text, text, text, jsonb, uuid)','ai_record(uuid, uuid, text, text, text[], text, text, integer, integer, numeric)',
    'ai_check_quota(uuid)','ai_save_briefing(uuid, date, jsonb, text)','ai_briefings_due()','ai_decide(uuid, boolean, jsonb)'] loop
    execute format('revoke execute on function biz.%s from public, anon', f);
    execute format('grant execute on function biz.%s to authenticated, service_role', f);
  end loop;
end $$;


-- =====================================================================================================================
-- 0012_chat.sql (converted to schema biz)
-- =====================================================================================================================
-- Ai buddy Biz — Chatwoot customer inbox bridge, Phase 2: Claude auto-reply and lead capture
-- Tables and functions used by the chatwoot-bridge Edge Function. Depends on 0001–0011.
-- All functions here are for the service role (the bridge) only; app users never call them.
-- NOT applied anywhere yet. Review first; on the EAB-QA-Test project use the generated incremental file in
-- supabase/eab-qa-test/ (schema biz).

-- ===== Which Chatwoot account belongs to which business =====
create table biz.chat_accounts (
  chatwoot_account_id int primary key,
  tenant_id uuid not null references biz.tenants(id) on delete cascade,
  bot_enabled boolean not null default true,        -- master switch for automatic replies
  max_bot_replies int not null default 6 check (max_bot_replies between 0 and 50),  -- per conversation, then a person takes over
  created_at timestamptz not null default now()
);
create index on biz.chat_accounts (tenant_id);

-- ===== One row per Chatwoot conversation the bridge has seen =====
create table biz.chat_conversations (
  chatwoot_account_id int not null references biz.chat_accounts(chatwoot_account_id) on delete cascade,
  chatwoot_conversation_id int not null,
  tenant_id uuid not null references biz.tenants(id) on delete cascade,
  contact_id uuid references biz.contacts(id) on delete set null,
  deal_id uuid references biz.deals(id) on delete set null,
  bot_replies int not null default 0,
  handed_over boolean not null default false,       -- once true the bot never replies in this conversation again
  handover_reason text,
  language text,
  last_summary text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (chatwoot_account_id, chatwoot_conversation_id)
);
create index on biz.chat_conversations (tenant_id, updated_at desc);
create index on biz.chat_conversations (deal_id);

-- ===== Webhook de-duplication (survives restarts and several running copies of the function) =====
create table biz.chat_events (
  dedupe_key text primary key,
  tenant_id uuid not null references biz.tenants(id) on delete cascade,
  at timestamptz not null default now()
);
create index on biz.chat_events (at);

alter table biz.chat_accounts enable row level security;
alter table biz.chat_conversations enable row level security;
alter table biz.chat_events enable row level security;      -- no policies: only the service role touches it

create policy chat_accounts_read on biz.chat_accounts for select using (has_perm(tenant_id, 'crm.settings.manage'));
create policy chat_accounts_write on biz.chat_accounts for all
  using (has_perm(tenant_id, 'crm.settings.manage')) with check (has_perm(tenant_id, 'crm.settings.manage'));
create policy chat_conversations_read on biz.chat_conversations for select using (has_perm(tenant_id, 'crm.deal.view'));

-- ===== Bridge functions (service role only) =====

-- First call for every webhook: find the business, and claim the event so the same delivery is handled only once.
create or replace function biz.chat_claim_event(p_account int, p_key text)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare a chat_accounts;
begin
  select * into a from chat_accounts where chatwoot_account_id = p_account;
  if not found then return jsonb_build_object('ok', false, 'reason', 'unknown_account'); end if;
  insert into chat_events (dedupe_key, tenant_id) values (left(p_key, 200), a.tenant_id) on conflict do nothing;
  if not found then return jsonb_build_object('ok', false, 'reason', 'duplicate'); end if;
  delete from chat_events where at < now() - interval '7 days';
  return jsonb_build_object('ok', true, 'tenant_id', a.tenant_id, 'bot_enabled', a.bot_enabled, 'max_bot_replies', a.max_bot_replies);
end $$;

-- A failed reply must not block Chatwoot's retry.
create or replace function biz.chat_release_event(p_key text)
returns void language sql security definer set search_path = biz, public as $$
  delete from chat_events where dedupe_key = left(p_key, 200);
$$;

-- Business facts for the prompt, plus this month's AI use against the plan limit (same counter as the in-app assistant).
create or replace function biz.chat_context(p_tenant uuid)
returns jsonb language sql stable security definer set search_path = biz, public as $$
  select jsonb_build_object(
    'business', t.name, 'country', t.country_code, 'currency', t.base_currency, 'plan', t.plan,
    'used', (select count(*) from ai_usage where tenant_id = t.id and at >= date_trunc('month', now())),
    'limit', coalesce((select monthly_requests from ai_plan_limits where plan = t.plan), 0))
  from tenants t where t.id = p_tenant;
$$;

create or replace function biz.chat_get_conversation(p_account int, p_conversation int)
returns jsonb language sql stable security definer set search_path = biz, public as $$
  select coalesce((select to_jsonb(c) from chat_conversations c
                   where c.chatwoot_account_id = p_account and c.chatwoot_conversation_id = p_conversation), '{}'::jsonb);
$$;

-- Create or update the contact and ONE lead (deal) per conversation from what the customer told the bot.
-- Never sets marketing consent: a customer messaging us is not consent to marketing.
create or replace function biz.chat_upsert_lead(p_tenant uuid, p_account int, p_conversation int, p jsonb)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare
  conv chat_conversations; cid uuid; did uuid; pid uuid; sid uuid; created boolean := false;
  v_name text := left(trim(coalesce(p->>'name','')), 120);
  v_phone text := left(trim(coalesce(p->>'phone','')), 40);
  v_email text := lower(left(trim(coalesce(p->>'email','')), 160));
  v_source text := left(coalesce(nullif(p->>'source',''), 'whatsapp'), 60);
  v_summary text := left(coalesce(p->>'summary',''), 1000);
  v_title text := left(coalesce(nullif(trim(p->>'interest'),''), 'Chat enquiry'), 160);
  v_values jsonb := coalesce(p->'values', '{}'::jsonb);
begin
  if not exists (select 1 from chat_accounts where chatwoot_account_id = p_account and tenant_id = p_tenant) then
    raise exception 'Unknown chat account';
  end if;
  if v_email <> '' and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then v_email := ''; end if;

  insert into chat_conversations (chatwoot_account_id, chatwoot_conversation_id, tenant_id)
  values (p_account, p_conversation, p_tenant) on conflict do nothing;
  select * into conv from chat_conversations
   where chatwoot_account_id = p_account and chatwoot_conversation_id = p_conversation for update;

  cid := conv.contact_id;
  if cid is null then
    select id into cid from contacts
     where tenant_id = p_tenant
       and ((v_phone <> '' and norm_phone(phone) = norm_phone(v_phone)) or (v_email <> '' and lower(email) = v_email))
     order by created_at limit 1;
  end if;
  if cid is null then
    insert into contacts (tenant_id, kind, name, phone, email, source, lifecycle)
    values (p_tenant, 'customer', coalesce(nullif(v_name,''), nullif(v_phone,''), 'Chat lead'), nullif(v_phone,''), nullif(v_email,''), v_source, 'lead')
    returning id into cid;
    created := true;
  else
    -- fill gaps only; never overwrite what staff or the customer already have on file
    update contacts set
      name  = case when v_name <> '' and name in ('Chat lead', coalesce(phone,'')) then v_name else name end,
      phone = coalesce(phone, nullif(v_phone,'')),
      email = coalesce(email, nullif(v_email,''))
    where id = cid;
  end if;

  did := conv.deal_id;
  if did is null then
    pid := ensure_pipeline(p_tenant);
    select id into sid from pipeline_stages where pipeline_id = pid and kind = 'open' order by sort_order limit 1;
    insert into deals (tenant_id, pipeline_id, stage_id, contact_id, title, value, currency, source, owner_id, custom_values)
    values (p_tenant, pid, sid, cid, v_title, 0, (select base_currency from tenants where id = p_tenant), v_source, null, v_values)
    returning id into did;
    created := true;
  else
    update deals set
      title = case when coalesce(p->>'interest','') <> '' then v_title else title end,
      custom_values = custom_values || v_values
    where id = did and tenant_id = p_tenant;
  end if;

  if v_summary <> '' and v_summary is distinct from conv.last_summary then
    insert into activities (tenant_id, contact_id, deal_id, kind, body, owner_id, created_by)
    values (p_tenant, cid, did, 'whatsapp', 'Chat summary (AI): ' || v_summary, null, null);
  end if;

  update chat_conversations set contact_id = cid, deal_id = did,
         language = coalesce(nullif(left(p->>'language', 10), ''), language),
         last_summary = coalesce(nullif(v_summary, ''), last_summary), updated_at = now()
   where chatwoot_account_id = p_account and chatwoot_conversation_id = p_conversation;

  return jsonb_build_object('contact_id', cid, 'deal_id', did, 'created', created);
end $$;

-- After every turn: count the AI use against the plan, count the reply, and remember a handover.
create or replace function biz.chat_record_turn(p_tenant uuid, p_account int, p_conversation int, p_replied boolean,
                                                   p_handover boolean, p_reason text, p_model text, p_in int, p_out int, p_cost numeric)
returns void language plpgsql security definer set search_path = biz, public as $$
begin
  insert into chat_conversations (chatwoot_account_id, chatwoot_conversation_id, tenant_id)
  values (p_account, p_conversation, p_tenant) on conflict do nothing;
  if coalesce(p_in, 0) + coalesce(p_out, 0) > 0 then
    insert into ai_usage (tenant_id, user_id, feature, input_tokens, output_tokens, cost_usd)
    values (p_tenant, null, 'chat_bot', p_in, p_out, p_cost);
  end if;
  update chat_conversations set
    bot_replies = bot_replies + case when p_replied then 1 else 0 end,
    handed_over = handed_over or coalesce(p_handover, false),
    handover_reason = case when coalesce(p_handover, false) and not handed_over then left(p_reason, 200) else handover_reason end,
    updated_at = now()
  where chatwoot_account_id = p_account and chatwoot_conversation_id = p_conversation and tenant_id = p_tenant;
end $$;

-- Service role only
do $$ declare f text; begin
  foreach f in array array[
    'chat_claim_event(int, text)', 'chat_release_event(text)', 'chat_context(uuid)', 'chat_get_conversation(int, int)',
    'chat_upsert_lead(uuid, int, int, jsonb)', 'chat_record_turn(uuid, int, int, boolean, boolean, text, text, int, int, numeric)'
  ] loop
    execute format('revoke execute on function biz.%s from public, anon, authenticated', f);
    execute format('grant execute on function biz.%s to service_role', f);
  end loop;
end $$;


-- =====================================================================================================================
-- 0013_chat_listings.sql (converted to schema biz)
-- =====================================================================================================================
-- Ai buddy Biz — Chatwoot customer inbox bridge, Phase 3: listings and viewing requests
-- Lets the chat assistant (a) look up listings from the product catalogue and (b) ask for a property viewing.
-- Depends on 0001–0012. Functions are for the service role (the bridge) only.
-- NOT applied anywhere yet. On the EAB-QA-Test project use the generated incremental file in supabase/eab-qa-test/.
--
-- Safety design:
--   * Opt-in. A product is visible to the chat assistant only when products.chat_visible = true (default false).
--   * The assistant only ever sees name, the lowest active variant price, the SKU as a reference, and products.chat_info —
--     text the owner wrote for exactly this purpose. Costs, stock levels, suppliers and custom fields are never exposed.
--   * A viewing request creates a PENDING booking plus a task for staff. Nothing is confirmed to the customer.

alter table biz.products
  add column chat_visible boolean not null default false,   -- may the chat assistant mention this product?
  add column chat_info text;                                -- what it may say: location, size, features… (owner-written)

-- ===== Viewing requests made from chat =====
create table biz.chat_viewing_requests (
  booking_id uuid primary key references biz.bookings(id) on delete cascade,
  tenant_id uuid not null references biz.tenants(id) on delete cascade,
  chatwoot_account_id int not null,
  chatwoot_conversation_id int not null,
  product_id uuid references biz.products(id) on delete set null,
  created_at timestamptz not null default now(),
  foreign key (chatwoot_account_id, chatwoot_conversation_id)
    references biz.chat_conversations(chatwoot_account_id, chatwoot_conversation_id) on delete cascade
);
create index on biz.chat_viewing_requests (chatwoot_account_id, chatwoot_conversation_id);
alter table biz.chat_viewing_requests enable row level security;
create policy chat_viewing_requests_read on biz.chat_viewing_requests for select
  using (has_perm(tenant_id, 'book.view') or has_perm(tenant_id, 'book.manage'));

-- ===== Listing search (service role only) =====
-- Every word of the query (max 5, 2+ letters) must appear in the product name or its chat_info.
-- An empty query returns the newest opted-in listings.
create or replace function biz.chat_search_listings(p_tenant uuid, p_query text default '', p_limit int default 5)
returns jsonb language plpgsql stable security definer set search_path = biz, public as $$
declare
  words text[];
  lim int := least(greatest(coalesce(p_limit, 5), 1), 8);
  cur char(3);
begin
  select base_currency into cur from tenants where id = p_tenant;
  select coalesce(array_agg(s.word), '{}') into words from (
    select lower(t) as word from unnest(regexp_split_to_array(trim(coalesce(p_query, '')), '\s+')) t where length(t) >= 2 limit 5
  ) s;
  return coalesce((
    select jsonb_agg(q.item) from (
      select jsonb_build_object('ref', v.sku, 'name', p.name, 'price_from', v.price, 'currency', cur,
                                'info', left(coalesce(p.chat_info, ''), 600)) as item
      from products p
      join lateral (select pv.sku, pv.price from product_variants pv where pv.product_id = p.id and pv.active order by pv.price, pv.sku limit 1) v on true
      where p.tenant_id = p_tenant and p.active and p.chat_visible
        and not exists (select 1 from unnest(words) w where position(w in lower(p.name || ' ' || coalesce(p.chat_info, ''))) = 0)
      order by p.created_at desc
      limit lim
    ) q), '[]'::jsonb);
end $$;

-- ===== Viewing request (service role only) =====
-- p: {"ref": SKU of the listing (optional), "start_local": "YYYY-MM-DD HH24:MI" in the business's time zone, "notes": text}
-- Returns {"ok": true, ...} or {"ok": false, "reason": ...}. Expected problems are reasons, not errors.
create or replace function biz.chat_request_viewing(p_tenant uuid, p_account int, p_conversation int, p jsonb)
returns jsonb language plpgsql security definer set search_path = biz, public as $$
declare
  conv chat_conversations; ct contacts; prod products;
  tz text := tenant_tz(p_tenant);
  v_local timestamp; v_start timestamptz; v_end timestamptz;
  v_ref text := left(trim(coalesce(p->>'ref', '')), 60);
  v_notes text := left(trim(coalesce(p->>'notes', '')), 300);
  svc uuid; outl uuid; bid uuid; existing uuid; n int; label text; shown text;
begin
  select * into conv from chat_conversations
   where chatwoot_account_id = p_account and chatwoot_conversation_id = p_conversation and tenant_id = p_tenant for update;
  if not found or conv.contact_id is null then return jsonb_build_object('ok', false, 'reason', 'no_contact'); end if;
  select * into ct from contacts where id = conv.contact_id;

  if coalesce(p->>'start_local', '') !~ '^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$' then
    return jsonb_build_object('ok', false, 'reason', 'bad_time');
  end if;
  begin
    v_local := (p->>'start_local')::timestamp;
  exception when others then
    return jsonb_build_object('ok', false, 'reason', 'bad_time');
  end;
  v_start := v_local at time zone tz;
  v_end := v_start + interval '60 minutes';
  shown := to_char(v_local, 'YYYY-MM-DD HH24:MI');
  if v_start < now() + interval '2 hours' then return jsonb_build_object('ok', false, 'reason', 'too_soon'); end if;
  if v_start > now() + interval '90 days' then return jsonb_build_object('ok', false, 'reason', 'too_far'); end if;

  -- same request again (customer repeats, or the webhook is retried): return the existing one
  select b.id into existing from bookings b join chat_viewing_requests r on r.booking_id = b.id
   where r.chatwoot_account_id = p_account and r.chatwoot_conversation_id = p_conversation
     and b.start_at = v_start and b.status in ('pending', 'confirmed');
  if existing is not null then
    return jsonb_build_object('ok', true, 'duplicate', true, 'booking_id', existing, 'start_local', shown);
  end if;

  select count(*) into n from chat_viewing_requests r join bookings b on b.id = r.booking_id
   where r.chatwoot_account_id = p_account and r.chatwoot_conversation_id = p_conversation and b.status in ('pending', 'confirmed');
  if n >= 3 then return jsonb_build_object('ok', false, 'reason', 'too_many_requests'); end if;

  select id into outl from outlets where tenant_id = p_tenant order by created_at limit 1;
  if outl is null then return jsonb_build_object('ok', false, 'reason', 'no_outlet'); end if;

  insert into booking_services (tenant_id, name, description, duration_minutes, price, online)
  values (p_tenant, 'Property viewing', 'Viewing requested through chat', 60, 0, false) on conflict (tenant_id, name) do nothing;
  select id into svc from booking_services where tenant_id = p_tenant and name = 'Property viewing';

  if v_ref <> '' then
    select p2.* into prod from products p2 join product_variants pv on pv.product_id = p2.id
     where p2.tenant_id = p_tenant and pv.sku = v_ref and p2.active and p2.chat_visible limit 1;
  end if;
  label := coalesce(prod.name, nullif(v_ref, ''), 'a property');

  insert into bookings (tenant_id, outlet_id, kind, service_id, contact_id, name, phone, email, party_size, start_at, end_at, status, source, notes)
  values (p_tenant, outl, 'service', svc, ct.id, ct.name, ct.phone, ct.email, 1, v_start, v_end, 'pending', 'web',
          left('Viewing request from chat, NOT confirmed. Property: ' || label || '.' || case when v_notes <> '' then ' Customer note: ' || v_notes else '' end, 1000))
  returning id into bid;

  insert into chat_viewing_requests (booking_id, tenant_id, chatwoot_account_id, chatwoot_conversation_id, product_id)
  values (bid, p_tenant, p_account, p_conversation, prod.id);

  insert into activities (tenant_id, contact_id, deal_id, kind, body, due_at, owner_id, created_by)
  values (p_tenant, ct.id, conv.deal_id, 'task', 'Confirm viewing requested via chat: ' || label || ' on ' || shown || ' (' || tz || '). Booking is pending.',
          now() + interval '1 hour', null, null);

  return jsonb_build_object('ok', true, 'duplicate', false, 'booking_id', bid, 'start_local', shown);
end $$;

-- Service role only
do $$ declare f text; begin
  foreach f in array array['chat_search_listings(uuid, text, int)', 'chat_request_viewing(uuid, int, int, jsonb)'] loop
    execute format('revoke execute on function biz.%s from public, anon, authenticated', f);
    execute format('grant execute on function biz.%s to service_role', f);
  end loop;
end $$;


commit;
select 'AI Buddy Biz installed in schema biz: ' || (select count(*) from pg_tables where schemaname = 'biz') || ' tables' as result;
